html:div.script:
// Show intro once per browser session; skip it on reloads within the same tab.
(function () {
    var seen = false;
    try { seen = sessionStorage.getItem('yyIntroSeen') === '1'; } catch (e) {}
    var intro = document.getElementById('intro');
    if (seen) { intro.remove(); return; }
    var yyBody = document.querySelector('body'); if (yyBody) yyBody.classList.add('intro-active');
    requestAnimationFrame(function () { intro.classList.add('play'); });
    document.getElementById('introContinue').addEventListener('click', function () {
        try { sessionStorage.setItem('yyIntroSeen', '1'); } catch (e) {}
        intro.classList.add('intro-hidden');
        var yyBody = document.querySelector('body'); if (yyBody) yyBody.classList.remove('intro-active');
        setTimeout(function () { intro.remove(); }, 900);
    });
})();

// ----- NAVIGATION -----
function navigateTo(pageId) {
    const wasOnGameplay = document.getElementById('page-gameplay').classList.contains('active');
    document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
    const target = document.getElementById('page-' + pageId);
    if (target) target.classList.add('active');
    if (wasOnGameplay && pageId !== 'gameplay') {
        setFrameSrc(document.getElementById('gameplayFrame'), 'about:blank', false);
    }
    document.querySelectorAll('.sidebar-icon').forEach(el => {
        el.classList.remove('active');
        if (el.dataset.page === pageId) el.classList.add('active');
    });
    document.querySelectorAll('.mobile-bottom-nav .nav-icon').forEach(el => {
        el.classList.remove('active');
        if (el.dataset.page === pageId) el.classList.add('active');
    });
    document.getElementById('urlBar').value = 'https://ying-yang-proxy.net/' + pageId;
    window.scrollTo({ top: 0, behavior: 'smooth' });
    syncTabForPage(pageId);
}

// ----- FAKE BROWSER TABS -----
// Every page, search or game the user opens gets its own tab in the strip above the
// address bar. Plain pages reuse an existing tab for the same page; searches, websites
// and games always open="true" a fresh tab.
const PAGE_TAB_INFO = {
    home: { icon: '☯', title: 'Home' },
    games: { icon: '🎮', title: 'Games' },
    ai: { icon: '🤖', title: 'AI' },
    anime: { icon: '🎌', title: 'Anime' },
    music: { icon: '🎵', title: 'Music' },
    chat: { icon: '💬', title: 'Chat' },
    add: { icon: '➕', title: 'Add' },
    allapps: { icon: '📦', title: 'All Apps' },
    discord: { icon: '💠', title: 'Discord' }
};
let browserTabs = [];
let activeTabId = null;
let tabIdCounter = 0;
let switchingTabs = false;   // true while a tab click is replaying its page (don't create tabs)
let pendingTab = null;       // details for the next navigateTo() that should open="true" a fresh tab
let forceNewPageTab = false; // "+" button: always open="true" a new Home tab

function getActiveTab() { return browserTabs.find(t => t.id === activeTabId) || null; }

function syncTabForPage(pageId) {
    if (switchingTabs) return;
    if (pendingTab) {
        const info = pendingTab;
        pendingTab = null;
        addTab(Object.assign({ pageId }, info));
        return;
    }
    if (pageId === 'gameplay' || pageId === 'search') return;
    const active = getActiveTab();
    let tab = (!forceNewPageTab && active && active.type === 'page' && active.pageId === pageId) ? active : null;
    if (!tab && !forceNewPageTab) tab = browserTabs.find(t => t.type === 'page' && t.pageId === pageId);
    forceNewPageTab = false;
    if (tab) { activeTabId = tab.id; renderTabs(); return; }
    const meta = PAGE_TAB_INFO[pageId] || { icon: '📄', title: pageId };
    addTab({ type: 'page', pageId, icon: meta.icon, title: pageId === 'games' && currentGameTab === 'movies' ? 'Movies' : meta.title });
}

function addTab(tab) {
    tab.id = ++tabIdCounter;
    browserTabs.push(tab);
    activeTabId = tab.id;
    renderTabs();
}

function renderTabs() {
    const list = document.getElementById('browserTabsList');
    list.innerHTML = '';
    browserTabs.forEach(tab => {
        const el = document.createElement('div');
        el.className = 'browser-tab' + (tab.id === activeTabId ? ' active' : '');
        el.setAttribute('role', 'tab');
        el.setAttribute('aria-selected', tab.id === activeTabId ? 'true' : 'false');
        el.title = tab.title;
        const icon = document.createElement('span');
        icon.className = 'tab-icon';
        icon.textContent = tab.icon;
        const title = document.createElement('span');
        title.className = 'tab-title';
        title.textContent = tab.title;
        const close = document.createElement('button');
        close.type = 'button';
        close.className = 'tab-close';
        close.setAttribute('aria-label', 'Close tab');
        close.textContent = '×';
        close.addEventListener('click', (e) => { e.stopPropagation(); closeTab(tab.id); });
        el.addEventListener('click', () => activateTab(tab.id));
        el.addEventListener('auxclick', (e) => { if (e.button === 1) { e.preventDefault(); closeTab(tab.id); } });
        el.append(icon, title, close);
        list.appendChild(el);
    });
    const activeEl = list.querySelector('.browser-tab.active');
    if (activeEl) activeEl.scrollIntoView({ block: 'nearest', inline: 'nearest' });
}

// Re-open whatever a tab was showing. Goes through window.navigateTo so other
// scripts' navigation hooks (e.g. community chat) still run.
function activateTab(id) {
    const tab = browserTabs.find(t => t.id === id);
    if (!tab) return;
    const alreadyActive = tab.id === activeTabId;
    activeTabId = tab.id;
    renderTabs();
    if (alreadyActive) return;
    switchingTabs = true;
    try {
        if (tab.type === 'gameplay') {
            showGameplay(tab.url, tab.title, tab.backTo);
            window.navigateTo('gameplay');
        } else if (tab.type === 'search') {
            showWebview(tab);
            window.navigateTo('search');
        } else {
            if (tab.pageId === 'games' && tab.gameTab && tab.gameTab !== currentGameTab) switchGameTab(tab.gameTab);
            window.navigateTo(tab.pageId);
        }
    } finally {
        switchingTabs = false;
    }
    if (tab.type === 'search') document.getElementById('urlBar').value = tab.url;
}

function closeTab(id) {
    const idx = browserTabs.findIndex(t => t.id === id);
    if (idx === -1) return;
    const wasActive = browserTabs[idx].id === activeTabId;
    const closed = browserTabs.splice(idx, 1)[0];
    if (!browserTabs.length) {
        activeTabId = null;
        if (closed.type === 'search') document.getElementById('webviewFrame').src = 'about:blank';
        window.navigateTo('home');
        return;
    }
    if (wasActive) {
        activeTabId = null;
        if (closed.type === 'search') document.getElementById('webviewFrame').src = 'about:blank';
        activateTab(browserTabs[Math.min(idx, browserTabs.length - 1)].id);
    } else {
        renderTabs();
    }
}

document.getElementById('browserTabNew').addEventListener('click', () => {
    forceNewPageTab = true;
    window.navigateTo('home');
    const input = document.getElementById('homeSearchInput');
    input.value = '';
    input.focus();
});

// ----- IN-SITE SEARCH / WEB VIEW -----
// Google's igu=1 mode is one of the few search pages that allows being shown inside an iframe.
function searchUrlFor(query) {
    return 'https://www.google.com/search?igu=1&q=' + encodeURIComponent(query);
}
function showWebview(tab) {
    const title = document.getElementById('webviewTitle');
    title.textContent = '';
    if (tab.query) {
        title.append('🔍 Results for ');
        const strong = document.createElement('strong');
        strong.textContent = tab.query;
        title.appendChild(strong);
    } else {
        title.textContent = '🌐 ' + tab.url;
    }
    document.getElementById('webviewExternal').href = tab.query
        ? 'https://www.google.com/search?q=' + encodeURIComponent(tab.query)
        : tab.url;
    const frame = document.getElementById('webviewFrame');
    frame.title = tab.title;
    frame.src = tab.url;
}
function openInSiteSearch(query) {
    const tab = { type: 'search', query, url: searchUrlFor(query), icon: '🔍', title: query };
    showWebview(tab);
    pendingTab = tab;
    window.navigateTo('search');
    document.getElementById('urlBar').value = tab.url;
}
function openInSiteUrl(url) {
    let host = url;
    try { host = new URL(url).hostname.replace(/^www\./, ''); } catch (e) {}
    const tab = { type: 'search', query: null, url, icon: '🌐', title: host };
    showWebview(tab);
    pendingTab = tab;
    window.navigateTo('search');
    document.getElementById('urlBar').value = url;
}
document.querySelectorAll('[data-page]').forEach(el => {
    el.addEventListener('click', function(e) {
        e.preventDefault();
        const page = this.dataset.page;
        if (page) navigateTo(page);
    });
});

// ----- LOCKED FRAMES (games + anime player) -----
// Keeps a game or episode frame on the exact page that was opened. If the page inside
// navigates anywhere else (e.g. a link back to the game site's homepage), the frame is put
// back on the original URL, so the user has to come back here to pick another game.
// Popups are also turned off while locked so the host site can't open="true" in a new tab.
const LOCK_RESET_LIMIT = 3;
const LOCK_RESET_WINDOW_MS = 10000;
function setFrameSrc(frame, url, locked) {
    frame.dataset.lockedUrl = locked ? url : '';
    frame.dataset.expectLoad = '1';
    frame._lockResets = [];
    const tokens = (frame.getAttribute('sandbox') || '').split(/\s+/).filter(t => t && t !== 'allow-popups');
    if (!locked) tokens.push('allow-popups');
    frame.setAttribute('sandbox', tokens.join(' '));
    frame.src = url;
}
function guardFrame(frame) {
    frame.addEventListener('load', () => {
        if (frame.dataset.expectLoad === '1') { frame.dataset.expectLoad = '0'; return; }
        const lockedUrl = frame.dataset.lockedUrl;
        if (!lockedUrl) return;
        // Some pages redirect themselves on purpose; stop fighting after a few quick resets
        // instead of reloading forever.
        const now = Date.now();
        frame._lockResets = (frame._lockResets || []).filter(t => now - t < LOCK_RESET_WINDOW_MS);
        if (frame._lockResets.length >= LOCK_RESET_LIMIT) return;
        frame._lockResets.push(now);
        frame.dataset.expectLoad = '1';
        frame.src = lockedUrl;
    });
}
guardFrame(document.getElementById('gameplayFrame'));
guardFrame(document.getElementById('animeFrame'));

// ----- LOAD ANIME SITE (raw external site, may be blocked by the site's own framing rules) -----
function loadAnimeSite(url) {
    setFrameSrc(document.getElementById('animeFrame'), url, false);
    document.getElementById('urlBar').value = url;
}

// ----- ANI.PM EMBEDDED PLAYER + BROWSABLE HOMEPAGE -----
// ani.pm publishes dedicated embed URLs (as opposed to framing its full site, which
// browsers block via X-Frame-Options), so this is what actually plays inside the app.
// The catalog below (posters, genres, synopses) also comes from ani.pm's own partner API —
// nothing here is scraped from unlicensed sources.
let animeState = { anilistId: 154587, episode: 1, lang: 'sub', totalEpisodes: null, title: "Frieren: Beyond Journey's End" };
let animeLastResults = [];
let animeActiveGenre = null;

// A handful of well-known titles used to seed the "Popular" grid via ani.pm's own search,
// so the homepage has something to browse instead of an empty search box.
const ANIME_POPULAR_QUERIES = [
    'Frieren', 'One Piece', 'Jujutsu Kaisen', 'Demon Slayer', 'Attack on Titan',
    'My Hero Academia', 'Spy x Family', 'Chainsaw Man', 'Naruto', 'Solo Leveling'
];

function animeEmbedUrl(anilistId, episode, lang) {
    return `https://ani.pm/embed/ani/${anilistId}/${episode}/${lang}`;
}

function playAnimeEmbed(anilistId, episode, lang, title) {
    animeState.anilistId = anilistId;
    animeState.episode = episode;
    animeState.lang = lang;
    if (title) animeState.title = title;
    setFrameSrc(document.getElementById('animeFrame'), animeEmbedUrl(anilistId, episode, lang), true);
    document.getElementById('animeEpisodeInput').value = episode;
    document.querySelectorAll('.anime-lang-btn').forEach(btn => {
        const active = btn.dataset.lang === lang;
        btn.classList.toggle('active', active);
        btn.style.background = active ? 'rgba(255,255,255,0.15)' : 'rgba(255,255,255,0.05)';
        btn.style.color = active ? '#fff' : 'rgba(255,255,255,0.6)';
    });
    updateNowPlayingLabel();
}

function updateNowPlayingLabel() {
    const epInfo = animeState.totalEpisodes ? `Episode ${animeState.episode} / ${animeState.totalEpisodes}` : `Episode ${animeState.episode}`;
    document.getElementById('animeNowPlaying').textContent = `${animeState.title} — ${epInfo} (${animeState.lang})`;
}

function renderAnimeHero(item) {
    const posterEl = document.getElementById('animeHeroPoster');
    posterEl.innerHTML = item.poster ? `<img src="${item.poster}" alt="${item.title || ''}"/>` : '🎬';
    document.getElementById('animeHeroTitle').textContent = item.title || animeState.title;
    const metaParts = [item.year, item.format, item.rating, item.score ? `★ ${item.score}` : null].filter(Boolean);
    document.getElementById('animeHeroMeta').textContent = metaParts.join(' · ');
    const genresEl = document.getElementById('animeHeroGenres');
    genresEl.innerHTML = '';
    (item.genres || []).forEach(g => {
        const span = document.createElement('span');
        span.className = 'anime-chip';
        span.style.cursor = 'default';
        span.textContent = g;
        genresEl.appendChild(span);
    });
    document.getElementById('animeHeroSynopsis').textContent = item.synopsis || '';
}

async="true" function fetchAnimeSeries(anilistId) {
    try {
        const res = await fetch(`https://ani.pm/api/partner/v1/series/${anilistId}`);
        if (!res.ok) return null;
        const json = await res.json();
        return json.data || null;
    } catch (e) {
        return null;
    }
}

async="true" function apiSearchTitles(query, limit) {
    try {
        const res = await fetch(`https://ani.pm/api/partner/v1/titles?q=${encodeURIComponent(query)}&limit=${limit}`);
        if (!res.ok) return [];
        const json = await res.json();
        return (json.data || []).filter(item => !item.adult);
    } catch (e) {
        return [];
    }
}

async="true" function searchAnime(query) {
    if (!query) return [];
    document.getElementById('animeGridTitle').textContent = `Searching for "${query}"...`;
    document.getElementById('animeBackLink').classList.remove('hidden');
    const results = await apiSearchTitles(query, 12);
    animeLastResults = results;
    animeActiveGenre = null;
    document.getElementById('animeGridTitle').textContent = results.length ? `Results for "${query}"` : `No results for "${query}"`;
    renderAnimeGenreChips(results);
    renderAnimeGrid(results);
    return results;
}

async="true" function loadPopularAnime() {
    document.getElementById('animeGridTitle').textContent = '🔥 Popular';
    document.getElementById('animeBackLink').classList.add('hidden');
    const batches = await Promise.all(ANIME_POPULAR_QUERIES.map(q => apiSearchTitles(q, 1)));
    const seen = new Set();
    const results = [];
    batches.forEach(batch => {
        batch.forEach(item => {
            if (item.anilistId && !seen.has(item.anilistId)) {
                seen.add(item.anilistId);
                results.push(item);
            }
        });
    });
    animeLastResults = results;
    animeActiveGenre = null;
    renderAnimeGenreChips(results);
    renderAnimeGrid(results);
}

function renderAnimeGenreChips(results) {
    const chipsEl = document.getElementById('animeGenreChips');
    const genres = [...new Set(results.flatMap(item => item.genres || []))].sort();
    chipsEl.innerHTML = '';
    genres.forEach(genre => {
        const chip = document.createElement('button');
        chip.className = 'anime-chip' + (animeActiveGenre === genre ? ' active' : '');
        chip.textContent = genre;
        chip.onclick = () => {
            animeActiveGenre = animeActiveGenre === genre ? null : genre;
            renderAnimeGenreChips(results);
            renderAnimeGrid(animeActiveGenre ? results.filter(item => (item.genres || []).includes(animeActiveGenre)) : results);
        };
        chipsEl.appendChild(chip);
    });
}

function renderAnimeGrid(results) {
    const gridEl = document.getElementById('animeBrowseGrid');
    gridEl.innerHTML = '';
    if (!results.length) {
        gridEl.innerHTML = '<span style="color:rgba(255,255,255,0.4);font-size:0.85rem;">Nothing to show — try a different search.</span>';
        return;
    }
    results.forEach(item => {
        const card = document.createElement('div');
        card.className = 'anime-card';
        const metaBits = [item.year, item.episodes ? `${item.episodes.total || item.episodes.sub || '?'} eps` : null].filter(Boolean).join(' · ');
        card.innerHTML = `
            <div class="anime-card-poster">
                ${item.poster ? `<img src="${item.poster}" alt="${item.title || ''}"/>` : '🎬'}
                <div class="anime-play-overlay">▶</div>
            </div>
            <div class="anime-card-info">
                <div class="anime-card-title">${item.title || 'Unknown title'}</div>
                <div class="anime-card-meta">${metaBits}</div>
            </div>`;
        card.onclick = () => selectAnimeResult(item);
        gridEl.appendChild(card);
    });
}

async="true" function selectAnimeResult(item) {
    animeState.totalEpisodes = item.episodes ? (item.episodes.sub || item.episodes.total || null) : null;
    renderAnimeHero(item);
    playAnimeEmbed(item.anilistId, 1, animeState.lang, item.title);
    document.querySelector('.anime-hero').scrollIntoView({ behavior: 'smooth', block: 'start' });
}

document.getElementById('animeSearchBtn').addEventListener('click', () => {
    searchAnime(document.getElementById('animeSearchInput').value.trim());
});
document.getElementById('animeSearchInput').addEventListener('keydown', (e) => {
    if (e.key === 'Enter') searchAnime(e.target.value.trim());
});
document.getElementById('animeBackLink').addEventListener('click', () => {
    document.getElementById('animeSearchInput').value = '';
    loadPopularAnime();
});
document.getElementById('animeEpisodeInput').addEventListener('change', (e) => {
    const ep = Math.max(1, parseInt(e.target.value, 10) || 1);
    playAnimeEmbed(animeState.anilistId, ep, animeState.lang);
});
document.getElementById('animePrevEp').addEventListener('click', () => {
    playAnimeEmbed(animeState.anilistId, Math.max(1, animeState.episode - 1), animeState.lang);
});
document.getElementById('animeNextEp').addEventListener('click', () => {
    playAnimeEmbed(animeState.anilistId, animeState.episode + 1, animeState.lang);
});
document.getElementById('animeSubBtn').addEventListener('click', () => {
    playAnimeEmbed(animeState.anilistId, animeState.episode, 'sub');
});
document.getElementById('animeDubBtn').addEventListener('click', () => {
    playAnimeEmbed(animeState.anilistId, animeState.episode, 'dub');
});

// Default: Frieren episode 1, sub — fetch its full details for the hero card, and seed the Popular grid.
fetchAnimeSeries(animeState.anilistId).then(data => {
    if (data) {
        if (data.episodes) animeState.totalEpisodes = data.episodes.sub || data.episodes.total || null;
        renderAnimeHero(data);
    }
    updateNowPlayingLabel();
});
loadPopularAnime();

// ----- HOME SEARCH (opens inside the site in a new tab) -----
document.getElementById('homeSearchInput').addEventListener('keydown', function(e) {
    if (e.key === 'Enter') {
        const q = this.value.trim();
        if (q) {
            openInSiteSearch(q);
            this.value = '';
            this.blur();
        }
    }
});

// ----- BROWSER BAR -----
document.getElementById('urlBar').addEventListener('keydown', function(e) {
    if (e.key === 'Enter') {
        let val = this.value.trim();
        if (val) {
            const sitePrefix = 'https://ying-yang-proxy.net/';
            if (val.startsWith(sitePrefix)) {
                const pageId = val.slice(sitePrefix.length).replace(/\/$/, '') || 'home';
                if (document.getElementById('page-' + pageId) && pageId !== 'gameplay' && pageId !== 'search') {
                    window.navigateTo(pageId);
                    this.blur();
                    return;
                }
            }
            if (!val.startsWith('http://') && !val.startsWith('https://')) {
                if (val.includes(' ') || !val.includes('.')) {
                    openInSiteSearch(val);
                } else {
                    openInSiteUrl('https://' + val);
                }
            } else {
                openInSiteUrl(val);
            }
            this.blur();
        }
    }
});

