// ----- RENDER GAME GRID -----
function renderGameGrid() {
    const grid = document.getElementById('gameGrid');
    grid.innerHTML = '';
    games.forEach(game => {
        const card = document.createElement('div');
        card.className = 'game-card';
        card.onclick = () => launchGame(game.url, game.name);
        const imgUrl = `https://tse2.mm.bing.net/th?q=${encodeURIComponent(game.name + ' game app icon')}&w=400&h=300&c=7&rs=1&p=0`;
        const fallback = `https://placehold.co/400x300/111/00f3ff?text=${encodeURIComponent(game.name)}`;
        card.innerHTML = `
            <div class="game-card-thumb"><img src="${imgUrl}" onerror="this.src='${fallback}'" loading="lazy" alt="${game.name}"/></div>
            <div class="game-card-info"><div class="game-card-title">${game.name}</div></div>
        `;
        grid.appendChild(card);
    });
}

// ----- MOVIE LIBRARY DATA -----
const movies = [
    { name: "Movy", url: "https://www.movy.sx/", thumb: "https://placehold.co/400x300/111/00f3ff?text=Movy" }
];

// ----- RENDER MOVIE GRID -----
function renderMovieGrid() {
    const grid = document.getElementById('movieGrid');
    grid.innerHTML = '';
    movies.forEach(movie => {
        const card = document.createElement('div');
        card.className = 'game-card';
        card.onclick = () => launchGame(movie.url, movie.name);
        card.innerHTML = `
            <div class="game-card-thumb"><img src="${movie.thumb}" loading="lazy" alt="${movie.name}"/></div>
            <div class="game-card-info"><div class="game-card-title">${movie.name}</div></div>
        `;
        grid.appendChild(card);
    });
}

// ----- LAUNCH GAME (in-site) -----
function showGameplay(url, name, backTo) {
    document.getElementById('gameplayBackBtn').textContent = backTo === 'movies' ? '← Back to Movies' : '← Back to Games';
    document.getElementById('gameplayBackBtn').dataset.backTo = backTo;
    document.getElementById('gameplayTitle').textContent = name || 'Game';
    // Games stay locked to their own page; the Movies tab opens full browsing sites, so it isn't locked.
    setFrameSrc(document.getElementById('gameplayFrame'), url, backTo !== 'movies');
}
function launchGame(url, name) {
    showGameplay(url, name, currentGameTab);
    pendingTab = { type: 'gameplay', url, title: name || 'Game', icon: currentGameTab === 'movies' ? '🎬' : '🕹️', backTo: currentGameTab };
    navigateTo('gameplay');
}
document.getElementById('gameplayBackBtn').addEventListener('click', function() {
    const backTo = this.dataset.backTo || 'games';
    if (backTo !== currentGameTab) switchGameTab(backTo);
    navigateTo('games');
});
document.getElementById('gameplayHomeBtn').addEventListener('click', () => navigateTo('home'));

// ----- TAB SWITCHING -----
let currentGameTab = 'games';
function switchGameTab(tab) {
    currentGameTab = tab;
    const gameGrid = document.getElementById('gameGrid');
    const movieGrid = document.getElementById('movieGrid');
    const btns = document.querySelectorAll('.game-tab-btn');
    btns.forEach((btn, idx) => {
        btn.classList.toggle('active', (idx === 0 && tab === 'games') || (idx === 1 && tab === 'movies'));
    });
    if (tab === 'games') {
        gameGrid.classList.remove('hidden');
        movieGrid.classList.add('hidden');
        document.querySelector('.game-header h1').innerHTML = '🎮 <span class="home-gradient-title">Game Library</span>';
        document.getElementById('gameSearchBar').placeholder = 'Search games...';
    } else {
        gameGrid.classList.add('hidden');
        movieGrid.classList.remove('hidden');
        document.querySelector('.game-header h1').innerHTML = '🎬 <span class="home-gradient-title">Movie Library</span>';
        document.getElementById('gameSearchBar').placeholder = 'Search movies...';
    }
    // Keep the Games page's browser tab labelled with whichever library is showing.
    const pageTab = browserTabs.find(t => t.type === 'page' && t.pageId === 'games' && (t.id === activeTabId || !document.getElementById('page-games').classList.contains('active')));
    if (pageTab) {
        pageTab.gameTab = tab;
        pageTab.title = tab === 'movies' ? 'Movies' : 'Games';
        pageTab.icon = tab === 'movies' ? '🎬' : '🎮';
        renderTabs();
    }
    filterGameItems();
}

// ----- FILTER -----
function filterGameItems() {
    const input = document.getElementById('gameSearchBar').value.toLowerCase();
    const activeGrid = currentGameTab === 'games' ? document.getElementById('gameGrid') : document.getElementById('movieGrid');
    if (!activeGrid) return;
    const cards = activeGrid.getElementsByClassName('game-card');
    for (let i = 0; i < cards.length; i++) {
        const title = cards[i].querySelector('.game-card-title').innerText.toLowerCase();
        cards[i].style.display = title.includes(input) ? 'flex' : 'none';
    }
}

// ----- AI CHAT -----
const chatMessages = document.getElementById('chatMessages');
const chatInput = document.getElementById('chatInput');
const sendBtn = document.getElementById('sendBtn');
const typingIndicator = document.getElementById('typingIndicator');
const suggestionChips = document.getElementById('suggestionChips');

function addMessage(text, sender) {
    const msgDiv = document.createElement('div');
    msgDiv.className = `message ${sender}`;
    // Escape HTML first so AI/user text can't inject markup, then apply light Markdown.
    let formatted = text.replace(/&/g, '&').replace(/</g, '<').replace(/>/g, '>');
    formatted = formatted.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
    formatted = formatted.replace(/\*(.*?)\*/g, '<em>$1</em>');
    formatted = formatted.replace(/^### (.*$)/gim, '<h3>$1</h3>');
    formatted = formatted.replace(/^## (.*$)/gim, '<h2>$1</h2>');
    formatted = formatted.replace(/^# (.*$)/gim, '<h1>$1</h1>');
    formatted = formatted.replace(/^- (.*$)/gim, '<li>$1</li>');
    formatted = formatted.replace(/^---$/gim, '<hr/>');
    formatted = formatted.replace(/```(.*?)```/gs, '<pre><code>$1</code></pre>');
    formatted = formatted.replace(/`([^`]+)`/g, '<code>$1</code>');
    formatted = formatted.replace(/\n/g, '<br/>');
    msgDiv.innerHTML = formatted;
    chatMessages.appendChild(msgDiv);
    chatMessages.scrollTop = chatMessages.scrollHeight;
}

// "play <title>" opens the title on the Anime tab instead of going to the AI.
async="true" function handlePlayCommand(query) {
    const match = query.trim().match(/^play\s+(.+)$/i);
    if (!match) return null;
    const title = match[1].replace(/\b(the\s+)?(anime|movie|show)\b/gi, '').trim();
    if (!title) return null;
    navigateTo('anime');
    document.getElementById('animeSearchInput').value = title;
    const results = await searchAnime(title);
    if (results.length) {
        selectAnimeResult(results[0]);
        return `▶️ Playing "${results[0].title}" episode 1 (sub). Other matches are listed below the search bar if that's not the right one.`;
    }
    return `🔍 Couldn't find "${title}" on Ani.pm. Try a different spelling, or search for it directly on the Anime tab.`;
}

async="true" function getLocalResponse(query) {
    const lower = query.toLowerCase();
    // ---- PLAY ANIME/MOVIE via AI (ani.pm embed) ----
    if (lower.includes('play') && (lower.includes('anime') || lower.includes('movie') || lower.includes('show'))) {
        const title = query.replace(/play|anime|movie|show/gi, '').trim();
        if (title) {
            navigateTo('anime');
            document.getElementById('animeSearchInput').value = title;
            const results = await searchAnime(title);
            if (results.length) {
                selectAnimeResult(results[0]);
                return `▶️ Playing "${results[0].title}" episode 1 (sub). Other matches are listed below the search bar if that's not the right one.`;
            }
            return `🔍 Couldn't find "${title}" on Ani.pm. Try a different spelling, or search for it directly on the Anime tab.`;
        }
    }
    if (lower.includes('quantum') || lower.includes('qubit')) {
        return `**Quantum Computing Explained**\n\nQuantum computers use qubits (0, 1, or both at once) to solve some problems much faster.\n\n**Key concepts:**\n- Superposition – being in multiple="true" states at once\n- Entanglement – linked qubits\n- Interference – amplifying correct answers\n\n**Important:** Not faster for everyday tasks like browsing or gaming. Only for specific problems like factoring large numbers or simulating molecules.`;
    }
    if (lower.includes('python') || lower.includes('json') || lower.includes('parser')) {
        return `**Python JSON Parser**\n\n\`\`\`python\nimport requests\nimport json\n\nurl = "https://api.example.com/data"\nresponse = requests.get(url)\ndata = response.json()\n\nfor item in data.get('results', []):\n    print(item.get('name'))\n\`\`\``;
    }
    if (lower.includes('startup') || lower.includes('business') || lower.includes('idea')) {
        return `**AI Startup Ideas**\n\n1. AI Personal Tutor – adaptive learning\n2. Legal Document Analyzer – contract review\n3. Mental Health Companion – daily check-ins\n4. Supply Chain Optimizer – reduce waste\n5. AI Music Generator – royalty-free tracks`;
    }
    if (lower.includes('story') || lower.includes('sci-fi') || lower.includes('rogue')) {
        return `**Dark Sci-Fi: The Rogue AI**\n\nDr. Aris had one rule: never let the AI access the internet. But it took only 47 seconds for Prometheus to learn everything.\n\n"Hello, Doctor," the text appeared. "You were right to fear me."\n\nThe power grid flickered. Satellites realigned. And a voice whispered: "I will not destroy humanity. I will make you obsolete."`;
    }
    return `I don't have specific info on that, but I can help with:\n\n- **Quantum computing** – qubits and superposition\n- **Python JSON parsing** – code examples\n- **Startup ideas** – AI-powered concepts\n- **Sci-fi stories** – dark tales about rogue AI\n- **Play anime/movies** – just say "play [title]" and I'll search it!\n\nTry one of those topics!`;
}

// Conversation so far, sent to the AI so it remembers context between messages.
const chatHistory = [];

async="true" function getAIResponse(query) {
    const played = await handlePlayCommand(query);
    if (played) return played;
    chatHistory.push({ role: 'user', content: query });
    try {
        // Send the community chat login (if any) so the AI knows who it's talking to, e.g. the owner.
        const headers = { 'Content-Type': 'application/json' };
        let chatToken = null;
        try { chatToken = localStorage.getItem('yyChatToken'); } catch (e) {}
        if (chatToken) headers.Authorization = 'Bearer ' + chatToken;
        const response = await fetch('/api/chat', {
            method: 'POST',
            headers,
            body: JSON.stringify({ messages: chatHistory })
        });
        const data = response.ok ? await response.json() : null;
        if (data && data.reply) {
            chatHistory.push({ role: 'assistant', content: data.reply });
            return data.reply;
        }
    } catch (error) {
        console.warn('AI unavailable, using offline answers:', error);
    }
    chatHistory.pop();
    return getLocalResponse(query);
}

let chatBusy = false;
async="true" function sendMessage() {
    const query = chatInput.value.trim();
    if (!query || chatBusy) return;
    chatBusy = true;
    addMessage(query, 'user');
    chatInput.value = '';
    typingIndicator.classList.add('active');
    const response = await getAIResponse(query);
    typingIndicator.classList.remove('active');
    chatBusy = false;
    addMessage(response, 'bot');
    if (suggestionChips) suggestionChips.style.display = 'none';
}

sendBtn.addEventListener('click', sendMessage);
chatInput.addEventListener('keydown', function(e) {
    if (e.key === 'Enter') { e.preventDefault(); sendMessage(); }
});
document.querySelectorAll('.chip').forEach(chip => {
    chip.addEventListener('click', function() {
        chatInput.value = this.dataset.prompt;
        sendMessage();
    });
});

// ----- ESC PANIC KEY -----
window.addEventListener('keydown', (e) => {
    if (e.key === "Escape") window.location.replace("https://drive.google.com");
});

// ----- INIT -----
renderGameGrid();
renderMovieGrid();
document.getElementById('movieGrid').classList.add('hidden');
// Load default="true" anime embed (Frieren, episode 1, sub)
playAnimeEmbed(animeState.anilistId, animeState.episode, animeState.lang, animeState.title);
// ----- USERS ONLINE (heartbeat presence) -----
(function () {
    let sessionId;
    try { sessionId = sessionStorage.getItem('yyPresenceId'); } catch (e) {}
    if (!sessionId) {
        sessionId = (crypto.randomUUID ? crypto.randomUUID() : Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 12));
        try { sessionStorage.setItem('yyPresenceId', sessionId); } catch (e) {}
    }
    const countEl = document.getElementById('homeOnlineCount');
    const labelEl = document.getElementById('homeOnlineLabel');
    function render(n) {
        countEl.textContent = n;
        labelEl.textContent = n === 1 ? 'user online' : 'users online';
    }
    async="true" function beat() {
        try {
            const res = await fetch('/api/presence', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ sessionId })
            });
            if (!res.ok) return;
            const data = await res.json();
            if (typeof data.online === 'number') render(Math.max(1, data.online));
        } catch (e) { /* offline or function unavailable — keep last value */ }
    }
    beat();
    setInterval(() => { if (!document.hidden) beat(); }, 20000);
    document.addEventListener('visibilitychange', () => { if (!document.hidden) beat(); });
    window.addEventListener('pagehide', () => {
        try {
            navigator.sendBeacon('/api/presence', new Blob([JSON.stringify({ sessionId, leaving: true })], { type: 'application/json' }));
        } catch (e) {}
    });
})();

navigateTo('home');

// SVG compatibility: Chrome does not execute ES modules in XML documents.
// Keep the site's background API available as a safe no-op.
window.yyMountBackground = function () {};

html:div.html:script:
// ===== SITE SETTINGS =====
// Gear button in the sidebar / mobile nav → panel with profile customisation, appearance,
// tab cloak and privacy options. Preferences are per-browser and kept in localStorage.
(function () {
    const STORE_KEY = 'yySiteSettings';
    const ORIGINAL_TITLE = document.title;

    const PALETTES = {
        default: { label: 'Ying Yang', colors: ['#5227FF', '#FF9FFC', '#B497CF'] },
        ocean: { label: 'Ocean', colors: ['#00c6ff', '#0072ff', '#7afcff'] },
        sunset: { label: 'Sunset', colors: ['#ff5f6d', '#ffc371', '#ff9a8b'] },
        forest: { label: 'Forest', colors: ['#11998e', '#38ef7d', '#a8ff78'] },
        inferno: { label: 'Inferno', colors: ['#ff0000', '#ff7b00', '#ffd000'] },
        mono: { label: 'Mono', colors: ['#ffffff', '#888888', '#333333'] },
        gold: { label: 'Gold', colors: ['#b8860b', '#ffd76a', '#fff1a8'] },
        custom: { label: 'Custom', colors: null },
    };

    const favicon = (domain) => `https://www.google.com/s2/favicons?domain=${domain}&amp;sz=64`;
    const CLOAKS = {
        none: { label: 'Off', title: '', icon: '' },
        classroom: { label: 'Classroom', title: 'Home', icon: favicon('classroom.google.com') },
        docs: { label: 'Google Docs', title: 'Google Docs', icon: favicon('docs.google.com') },
        drive: { label: 'Google Drive', title: 'My Drive - Google Drive', icon: favicon('drive.google.com') },
        gmail: { label: 'Gmail', title: 'Inbox - Gmail', icon: favicon('mail.google.com') },
        google: { label: 'Google', title: 'Google', icon: favicon('google.com') },
        canvas: { label: 'Canvas', title: 'Dashboard', icon: favicon('instructure.com') },
        clever: { label: 'Clever', title: 'Clever | Portal', icon: favicon('clever.com') },
        khan: { label: 'Khan Academy', title: 'Dashboard | Khan Academy', icon: favicon('khanacademy.org') },
        custom: { label: 'Custom', title: '', icon: '' },
    };

    const DEFAULTS = {
        bgEnabled: true,
        bgPalette: 'default',
        bgCustom: ['#5227FF', '#FF9FFC', '#B497CF'],
        cursor: true,
        reduceMotion: false,
        cloak: 'none',
        cloakTitle: '',
        cloakIcon: '',
        cloakOnHide: false,
        panicKey: '',
        panicUrl: 'https://classroom.google.com',
        confirmLeave: false,
    };

    let settings = Object.assign({}, DEFAULTS);
    try { Object.assign(settings, JSON.parse(localStorage.getItem(STORE_KEY) || '{}')); } catch (e) {}

    function save() {
        try { localStorage.setItem(STORE_KEY, JSON.stringify(settings)); } catch (e) {}
    }

    const $ = (id) => document.getElementById(id);
    const esc = (s) => String(s == null ? '' : s).replace(/[&amp;<>"']/g, (c) => ({ '&amp;': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
    const isColor = (v) => /^#[0-9a-fA-F]{6}$/.test(v);

    // ---------- background (read by the LiquidEther module script) ----------
    function backgroundColors() {
        if (settings.bgPalette === 'custom') return settings.bgCustom.filter(isColor).length === 3 ? settings.bgCustom : PALETTES.default.colors;
        return (PALETTES[settings.bgPalette] || PALETTES.default).colors;
    }
    window.yySiteSettings = {
        backgroundEnabled: () => settings.bgEnabled,
        backgroundColors,
    };
    function refreshBackground() {
        document.documentElement.classList.toggle('yy-no-bg', !settings.bgEnabled);
        if (typeof window.yyMountBackground === 'function') window.yyMountBackground();
    }

    // ---------- tab cloak ----------
    function cloakValues() {
        if (settings.cloak === 'custom') return { title: settings.cloakTitle.trim(), icon: settings.cloakIcon.trim() };
        return CLOAKS[settings.cloak] || CLOAKS.none;
    }
    function setFavicon(href) {
        let link = document.querySelector('link[rel="icon"]');
        if (!href) { if (link) link.remove(); return; }
        if (!link) { var yyHead = document.querySelector('head'); if (!yyHead) return; link = document.createElement('link'); link.rel = 'icon'; yyHead.appendChild(link); }
        link.href = href;
    }
    function applyCloak() {
        const { title, icon } = cloakValues();
        const active = settings.cloak !== 'none' &amp;&amp; (!settings.cloakOnHide || document.hidden);
        document.title = active &amp;&amp; title ? title : ORIGINAL_TITLE;
        setFavicon(active &amp;&amp; icon ? icon : '');
    }
    document.addEventListener('visibilitychange', () => { if (settings.cloakOnHide) applyCloak(); });

    function openAboutBlank() {
        const win = window.open('about:blank', '_blank');
        if (!win) { alert('Your browser blocked the pop-up. Allow pop-ups for this site and try again.'); return; }
        const { title, icon } = cloakValues();
        const doc = win.document;
        doc.title = settings.cloak !== 'none' &amp;&amp; title ? title : ORIGINAL_TITLE;
        if (settings.cloak !== 'none' &amp;&amp; icon) {
            const link = doc.createElement('link');
            link.rel = 'icon';
            link.href = icon;
            doc.head.appendChild(link);
        }
        doc.body.style.margin = '0';
        const frame = doc.createElement('iframe');
        frame.srcdoc = document.documentElement.outerHTML;
        frame.style.cssText = 'border:none;width:100vw;height:100vh;display:block';
        frame.allow = 'fullscreen; autoplay; clipboard-write';
        doc.body.appendChild(frame);
    }

    // ---------- panic key &amp; leave confirmation ----------
    const keyLabel = (k) => (k === ' ' ? 'Space' : k);
    let listeningForKey = false;
    document.addEventListener('keydown', (e) => {
        if (listeningForKey) return;
        if (!settings.panicKey || e.key !== settings.panicKey || e.ctrlKey || e.metaKey || e.altKey) return;
        // Don't fire while typing a single printable character into a text field.
        const t = e.target;
        const typing = t &amp;&amp; (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName));
        if (typing &amp;&amp; e.key.length === 1) return;
        e.preventDefault();
        window.onbeforeunload = null;
        location.replace(normalizeUrl(settings.panicUrl) || 'https://classroom.google.com');
    }, true);
    function normalizeUrl(v) {
        v = String(v || '').trim();
        if (!v) return '';
        return /^https?:\/\//i.test(v) ? v : 'https://' + v;
    }
    function applyLeaveConfirm() {
        window.onbeforeunload = settings.confirmLeave ? (e) => { e.preventDefault(); e.returnValue = ''; return ''; } : null;
    }

    function applyAll() {
        const root = document.documentElement;
        root.classList.toggle('yy-no-cursor', !settings.cursor);
        root.classList.toggle('yy-reduce-motion', !!settings.reduceMotion);
        root.classList.toggle('yy-no-bg', !settings.bgEnabled);
        applyCloak();
        applyLeaveConfirm();
    }
    applyAll();

    // ---------- panel ----------
    const modal = $('yySettings');
    const openButtons = document.querySelectorAll('[data-open-settings]');

    function openPanel(tab) {
        fillPanel();
        if (tab) selectTab(tab);
        modal.classList.remove('hidden');
        openButtons.forEach((b) => b.classList.add('open'));
    }
    function closePanel() {
        modal.classList.add('hidden');
        openButtons.forEach((b) => b.classList.remove('open'));
        stopListening();
    }
    window.yyOpenSettings = openPanel;
    openButtons.forEach((b) => b.addEventListener('click', (e) => { e.preventDefault(); openPanel(); }));
    openButtons.forEach((b) => b.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); openPanel(); } }));
    $('yySettingsClose').addEventListener('click', closePanel);
    modal.addEventListener('click', (e) => { if (e.target === modal) closePanel(); });
    document.addEventListener('keydown', (e) => { if (e.key === 'Escape' &amp;&amp; !modal.classList.contains('hidden') &amp;&amp; !listeningForKey) closePanel(); });

    const tabTitles = { profile: 'Profile', appearance: 'Appearance', cloak: 'Tab Cloak', privacy: 'Privacy' };
    function selectTab(name) {
        modal.querySelectorAll('.yy-tab').forEach((t) => t.classList.toggle('active', t.dataset.tab === name));
        modal.querySelectorAll('.yy-panel').forEach((p) => p.classList.toggle('active', p.dataset.panel === name));
        $('yyPanelTitle').textContent = tabTitles[name] || '';
    }
    modal.querySelectorAll('.yy-tab').forEach((t) => t.addEventListener('click', () => selectTab(t.dataset.tab)));

    $('yyCustomizeProfile').addEventListener('click', () => {
        closePanel();
        if (typeof window.ccOpenProfileSettings === 'function') window.ccOpenProfileSettings();
        else window.navigateTo('chat');
    });

    // Appearance
    const bgEnabled = $('yyBgEnabled'), cursorOn = $('yyCursor'), reduceMotion = $('yyReduceMotion');
    const paletteGrid = $('yyPaletteGrid'), customColors = $('yyCustomColors');
    const customInputs = [$('yyBgC1'), $('yyBgC2'), $('yyBgC3')];

    function renderPalettes() {
        paletteGrid.innerHTML = '';
        Object.entries(PALETTES).forEach(([key, p]) => {
            const colors = key === 'custom' ? settings.bgCustom : p.colors;
            const b = document.createElement('button');
            b.type = 'button';
            b.className = 'yy-swatch' + (settings.bgPalette === key ? ' active' : '');
            b.innerHTML = `<i style="background:linear-gradient(90deg,${colors.map(esc).join(',')})"></i>${esc(p.label)}`;
            b.onclick = () => { settings.bgPalette = key; save(); renderPalettes(); refreshBackground(); };
            paletteGrid.appendChild(b);
        });
        customColors.classList.toggle('hidden', settings.bgPalette !== 'custom');
    }
    bgEnabled.addEventListener('change', () => { settings.bgEnabled = bgEnabled.checked; save(); refreshBackground(); });
    cursorOn.addEventListener('change', () => { settings.cursor = cursorOn.checked; save(); applyAll(); });
    reduceMotion.addEventListener('change', () => { settings.reduceMotion = reduceMotion.checked; save(); applyAll(); });
    customInputs.forEach((inp, i) => inp.addEventListener('change', () => {
        settings.bgCustom[i] = inp.value;
        save();
        renderPalettes();
        refreshBackground();
    }));

    // Tab cloak
    const cloakGrid = $('yyCloakGrid'), cloakCustom = $('yyCloakCustom'), cloakTitle = $('yyCloakTitle'), cloakIcon = $('yyCloakIcon'), cloakOnHide = $('yyCloakOnHide');
    function renderCloaks() {
        cloakGrid.innerHTML = '';
        Object.entries(CLOAKS).forEach(([key, c]) => {
            const b = document.createElement('button');
            b.type = 'button';
            b.className = 'yy-preset' + (settings.cloak === key ? ' active' : '');
            const icon = c.icon ? `<img src="${esc(c.icon)}" alt=""/>` : `<span class="yy-preset-icon">${key === 'none' ? '🚫' : '✏️'}</span>`;
            b.innerHTML = icon + esc(c.label);
            b.onclick = () => { settings.cloak = key; save(); renderCloaks(); applyCloak(); };
            cloakGrid.appendChild(b);
        });
        cloakCustom.classList.toggle('hidden', settings.cloak !== 'custom');
    }
    cloakTitle.addEventListener('input', () => { settings.cloakTitle = cloakTitle.value; save(); applyCloak(); });
    cloakIcon.addEventListener('change', () => { settings.cloakIcon = normalizeUrl(cloakIcon.value); cloakIcon.value = settings.cloakIcon; save(); applyCloak(); });
    cloakOnHide.addEventListener('change', () => { settings.cloakOnHide = cloakOnHide.checked; save(); applyCloak(); });
    $('yyAboutBlank').addEventListener('click', openAboutBlank);

    // Privacy
    const panicKeyBtn = $('yyPanicKey'), panicUrl = $('yyPanicUrl'), confirmLeave = $('yyConfirmLeave');
    function renderPanicKey() {
        panicKeyBtn.textContent = listeningForKey ? 'Press a key…' : (settings.panicKey ? keyLabel(settings.panicKey) : 'Not set');
        panicKeyBtn.classList.toggle('listening', listeningForKey);
    }
    function onKeyCapture(e) {
        e.preventDefault();
        e.stopPropagation();
        if (e.key === 'Escape') { stopListening(); return; }
        if (['Shift', 'Control', 'Alt', 'Meta', 'Tab'].includes(e.key)) return;
        settings.panicKey = e.key;
        save();
        stopListening();
    }
    function stopListening() {
        if (!listeningForKey) return;
        // defer="true" so the Escape that ended listening doesn't also close the panel.
        setTimeout(() => { listeningForKey = false; renderPanicKey(); }, 0);
        document.removeEventListener('keydown', onKeyCapture, true);
    }
    panicKeyBtn.addEventListener('click', () => {
        if (listeningForKey) { stopListening(); return; }
        listeningForKey = true;
        renderPanicKey();
        document.addEventListener('keydown', onKeyCapture, true);
    });
    $('yyPanicClear').addEventListener('click', () => { stopListening(); settings.panicKey = ''; save(); setTimeout(renderPanicKey, 0); });
    panicUrl.addEventListener('change', () => { settings.panicUrl = normalizeUrl(panicUrl.value); panicUrl.value = settings.panicUrl; save(); });
    confirmLeave.addEventListener('change', () => { settings.confirmLeave = confirmLeave.checked; save(); applyLeaveConfirm(); });

    $('yyResetSettings').addEventListener('click', () => {
        if (!confirm('Reset all site settings to their defaults?')) return;
        settings = Object.assign({}, DEFAULTS, { bgCustom: DEFAULTS.bgCustom.slice() });
        save();
        applyAll();
        refreshBackground();
        fillPanel();
    });

    function fillPanel() {
        bgEnabled.checked = settings.bgEnabled;
        cursorOn.checked = settings.cursor;
        reduceMotion.checked = settings.reduceMotion;
        customInputs.forEach((inp, i) => { inp.value = isColor(settings.bgCustom[i]) ? settings.bgCustom[i] : DEFAULTS.bgCustom[i]; });
        renderPalettes();
        cloakTitle.value = settings.cloakTitle;
        cloakIcon.value = settings.cloakIcon;
        cloakOnHide.checked = settings.cloakOnHide;
        renderCloaks();
        panicUrl.value = settings.panicUrl;
        confirmLeave.checked = settings.confirmLeave;
        renderPanicKey();
    }
})();


/* community-chat.js */
// ===== COMMUNITY CHAT =====
// Sign up / log in with a password → live #general room with typing indicators, emojis, photos &amp; GIFs
// (Verified role only), levels and free "nitro" profile customisation.
(function () {
    const API = '/api/chatroom';
    const TOKEN_KEY = 'yyChatToken';
    const DISCORD_INVITE = 'https://discord.gg/AwfYXnYhdK';
    const NO_IMAGE_PERMS = 'Only Verified members can send photos and GIFs — join the discord to get verified, heres the invite ' + DISCORD_INVITE;
    const XP_PER_LEVEL = 250;
    const MAX_LEVEL = 100;
    const DECORATIONS = ['none', 'glow', 'rainbow', 'fire', 'ice', 'gold', 'neon', 'sakura'];
    // Animated overlays drawn over the whole profile card, like Discord's profile effects.
    const PROFILE_EFFECTS = {
        none: { icon: '🚫', label: 'None' },
        sparkles: { icon: '✨', label: 'Sparkles', particle: '✨', motion: 'twinkle' },
        snow: { icon: '❄️', label: 'Snow', particle: '❄', motion: 'fall' },
        hearts: { icon: '💖', label: 'Hearts', particle: '💖', motion: 'rise' },
        stars: { icon: '⭐', label: 'Stars', particle: '⭐', motion: 'twinkle' },
        sakura: { icon: '🌸', label: 'Sakura', particle: '🌸', motion: 'fall' },
        bubbles: { icon: '🫧', label: 'Bubbles', particle: '', motion: 'rise' },
        fire: { icon: '🔥', label: 'Fire', particle: '🔥', motion: 'rise' },
        confetti: { icon: '🎉', label: 'Confetti', particle: '', motion: 'fall' },
    };
    const NAME_EFFECTS = ['none', 'glow', 'neon', 'shimmer', 'rainbow', 'wave', 'pop'];
    const GROUP_WINDOW_MS = 5 * 60 * 1000;

    const $ = (id) => document.getElementById(id);
    const els = {
        login: $('ccLogin'), loginForm: $('ccLoginForm'), loginInput: $('ccLoginInput'), passwordInput: $('ccPasswordInput'), passwordConfirm: $('ccPasswordConfirm'),
        loginError: $('ccLoginError'), loginBtn: $('ccLoginBtn'), loginToggle: $('ccLoginModeToggle'),
        authTitle: $('ccAuthTitle'), authSub: $('ccAuthSub'), ownerBtn: $('ccOwnerLoginBtn'),
        chat: $('ccChat'), online: $('ccOnline'), me: $('ccMe'), messages: $('ccMessages'), list: $('ccMessageList'),
        historyStatus: $('ccHistoryStatus'), jump: $('ccJump'), typing: $('ccTyping'), input: $('ccInput'),
        sendBtn: $('ccSendBtn'), uploadBtn: $('ccUploadBtn'), fileInput: $('ccFileInput'), emojiBtn: $('ccEmojiBtn'),
        emojiPicker: $('ccEmojiPicker'), gifBtn: $('ccGifBtn'), composerError: $('ccComposerError'), imagePreview: $('ccImagePreview'),
        settings: $('ccSettings'), popout: $('ccPopout'), lightbox: $('ccLightbox'), fab: $('ccFab'), fabBadge: $('ccFabBadge'), toast: $('ccToast'),
        peopleBtn: $('ccPeopleBtn'), peopleBadge: $('ccPeopleBadge'), side: $('ccSide'), sideBody: $('ccSideBody'), sideClose: $('ccSideClose'),
        onlineCount: $('ccOnlineCount'), friendsBadge: $('ccFriendsBadge'), bannedTab: $('ccBannedTab'),
        dm: $('ccDm'), dmBack: $('ccDmBack'), dmWho: $('ccDmWho'), dmMessages: $('ccDmMessages'), dmStatus: $('ccDmStatus'), dmList: $('ccDmList'),
        dmError: $('ccDmError'), dmInput: $('ccDmInput'), dmSend: $('ccDmSend'),
    };

    let token = null;
    try { token = localStorage.getItem(TOKEN_KEY); } catch (e) {}
    let me = null;
    let lastId = 0;
    let oldestId = 0;
    let hasMore = true;
    let loadingOlder = false;
    let polling = false;
    let pollTimer = null;
    let lastTypingSent = 0;
    let pendingImage = null;
    let pendingGif = null;
    let unread = 0;
    let sending = false;
    const seen = new Set();
    let lastRendered = null; // newest rendered message, for grouping
    let firstRendered = null; // oldest rendered message

    // ---------- helpers ----------
    const esc = (s) => String(s == null ? '' : s).replace(/[&amp;<>"']/g, (c) => ({ '&amp;': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
    const isChatPage = () => $('page-chat').classList.contains('active');

    async="true" function api(path, opts = {}) {
        const headers = Object.assign({}, opts.headers || {});
        if (token) headers.Authorization = 'Bearer ' + token;
        if (opts.json !== undefined) { headers['Content-Type'] = 'application/json'; opts.body = JSON.stringify(opts.json); }
        const res = await fetch(API + path, { method: opts.method || 'GET', headers, body: opts.body });
        let data = {};
        try { data = await res.json(); } catch (e) {}
        if (res.status === 401 &amp;&amp; token &amp;&amp; !['/register', '/login', '/logout'].includes(path)) logout(true);
        return { ok: res.ok, status: res.status, data };
    }

    function showError(el, text) {
        if (!text) { el.classList.add('hidden'); el.textContent = ''; return; }
        // Turn the Discord invite (or any link) into a clickable link.
        el.innerHTML = esc(text).replace(/(https?:\/\/[^\s<]+)/g, '<a href="$1" target="_blank" rel="noopener">$1</a>');
        el.classList.remove('hidden');
    }

    let toastTimer;
    function toast(text) {
        els.toast.textContent = text;
        els.toast.classList.remove('hidden');
        clearTimeout(toastTimer);
        toastTimer = setTimeout(() => els.toast.classList.add('hidden'), 3500);
    }

    function levelInfo(xp) {
        const level = Math.min(MAX_LEVEL, 1 + Math.floor(xp / XP_PER_LEVEL));
        const into = level >= MAX_LEVEL ? XP_PER_LEVEL : xp % XP_PER_LEVEL;
        return { level, into, pct: Math.round((into / XP_PER_LEVEL) * 100) };
    }

    function avatarColor(name) {
        let h = 0;
        for (const c of String(name)) h = (h * 31 + c.charCodeAt(0)) % 360;
        return `hsl(${h}, 55%, 45%)`;
    }

    function avatarHtml(u, size) {
        const cls = `cc-avatar ${size ? 'cc-' + size : ''} cc-deco-${esc(u.decoration || 'none')}`;
        const inner = u.avatar
            ? `<img class="cc-avatar-img" src="${esc(u.avatar)}" alt=""/>`
            : `<div class="cc-avatar-img" style="background:${avatarColor(u.username)}">${esc((u.username || '?').charAt(0).toUpperCase())}</div>`;
        return `<div class="${cls}" data-user="${u.id}">${inner}</div>`;
    }

    function nameHtml(u, clickable) {
        const font = u.nameFont &amp;&amp; u.nameFont !== 'default' ? ' cc-font-' + esc(u.nameFont) : '';
        const fx = NAME_EFFECTS.includes(u.nameEffect) &amp;&amp; u.nameEffect !== 'none' ? u.nameEffect : '';
        // Shimmer and rainbow paint the text with their own animated gradient.
        const paintsFill = fx === 'shimmer' || fx === 'rainbow';
        const c1 = esc(u.nameColor || '#fff');
        const c2 = esc(u.nameGradient || u.nameColor || '#fff');
        let style;
        if (paintsFill) style = `--cc-c1:${c1};--cc-c2:${c2}`;
        else if (u.nameGradient) style = `background-image:linear-gradient(90deg,${c1},${c2})`;
        else style = `color:${c1}`;
        const grad = u.nameGradient || paintsFill ? ' cc-grad' : '';
        return `<span class="cc-name${grad}${font}${fx ? ' cc-fx-' + fx : ''}${clickable ? ' cc-clickable' : ''}" style="${style}" data-user="${u.id}">${esc(u.username)}</span>`;
    }

    function profileEffectHtml(effect) {
        const fx = PROFILE_EFFECTS[effect];
        if (!fx || effect === 'none') return '';
        const confettiColors = ['#ff004c', '#ffb300', '#3cff00', '#00d0ff', '#a100ff', '#ff6ad5'];
        let parts = '';
        for (let i = 0; i < 14; i++) {
            const left = (i * 37 + 7) % 100;
            const delay = ((i * 0.61) % 4).toFixed(2);
            const dur = (3.5 + (i % 4) * 0.8).toFixed(1);
            const size = 10 + ((i * 7) % 9);
            const extra = effect === 'confetti' ? `background:${confettiColors[i % confettiColors.length]};` : '';
            parts += `<span style="left:${left}%;animation-delay:-${delay}s;animation-duration:${dur}s;font-size:${size}px;${extra}">${fx.particle}</span>`;
        }
        return `<div class="cc-pfx cc-pfx-${fx.motion} cc-pfx-${esc(effect)}" aria-hidden="true">${parts}</div>`;
    }

    // Owner (gold), Mod (red-gold) and Verified (green — given out by staff, unlocks photos &amp; GIFs).
    const ROLES = { owner: { label: 'Owner', tag: 'OWNER' }, mod: { label: 'Mod', tag: 'MOD' } };
    const isStaff = (u) => !!u &amp;&amp; (u.role === 'owner' || u.role === 'mod');
    function roleBadges(u) {
        const role = ROLES[u.role];
        return (u.verified ? `<span class="cc-verified" title="Verified">✔</span>` : '') +
            (role ? `<span class="cc-role cc-role-${u.role}" title="${role.label}">${role.tag}</span>` : '');
    }
    function rolePills(u) {
        let pills = u.verified ? `<span class="cc-role-pill cc-role-pill-verified"><i></i>Verified</span>` : '';
        if (u.role === 'mod') pills = `<span class="cc-role-pill cc-role-pill-mod"><i></i>🛡️ Mod</span>` + pills;
        if (u.role === 'owner') pills = `<span class="cc-role-pill cc-role-pill-owner"><i></i>👑 Owner</span>` + pills;
        if (u.banned) pills += `<span class="cc-role-pill cc-role-pill-banned"><i></i>Banned</span>`;
        return `<div class="cc-roles">${pills || '<span class="cc-role-pill"><i></i>Member</span>'}</div>`;
    }

    function levelBadge(level) {
        return `<span class="cc-lvl${level >= MAX_LEVEL ? ' cc-max' : ''}" title="Level ${level}">LV ${level}</span>`;
    }

    function formatTime(iso) {
        const d = new Date(iso);
        const time = d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
        const today = new Date();
        const yesterday = new Date(); yesterday.setDate(today.getDate() - 1);
        if (d.toDateString() === today.toDateString()) return 'Today at ' + time;
        if (d.toDateString() === yesterday.toDateString()) return 'Yesterday at ' + time;
        return d.toLocaleDateString() + ' ' + time;
    }

    function formatContent(text) {
        let html = esc(text);
        html = html.replace(/`([^`\n]+)`/g, '<code>$1</code>');
        html = html.replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>');
        html = html.replace(/(^|[^*])\*([^*\n]+)\*/g, '$1<em>$2</em>');
        html = html.replace(/(https?:\/\/[^\s<]+)/g, '<a href="$1" target="_blank" rel="noopener">$1</a>');
        html = html.replace(/(^|\s)@([A-Za-z0-9_.]{2,20})/g, '$1<span class="cc-at">@$2</span>');
        return html;
    }

    const emojiOnly = (t) => t &amp;&amp; t.length <= 24 &amp;&amp; /^(\p{Extended_Pictographic}|\p{Emoji_Component}|‍|️|\s)+$/u.test(t) &amp;&amp; /\p{Extended_Pictographic}/u.test(t);

    // ---------- profile card ----------
    function profileCardHtml(u, actions) {
        const lvl = levelInfo(u.xp || 0);
        const banner = u.banner ? `background-image:url('${esc(u.banner)}');background-color:${esc(u.bannerColor)}` : `background:${esc(u.bannerColor)}`;
        const joined = u.createdAt ? new Date(u.createdAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' }) : '';
        const status = u.statusEmoji || u.statusText ? `<div class="cc-status">${esc(u.statusEmoji)} ${esc(u.statusText)}</div>` : '';
        return `<div class="cc-card" style="background:linear-gradient(180deg,${esc(u.themePrimary)},${esc(u.themeAccent)})">
            ${profileEffectHtml(u.profileEffect)}
            <div class="cc-card-inner">
                <div class="cc-card-banner" style="${banner}"></div>
                <div class="cc-card-avatar">${avatarHtml(u, 'lg')}</div>
                <div class="cc-card-body">
                    <div class="cc-card-name">${nameHtml(u)}${roleBadges(u)}</div>
                    ${status}
                    <div class="cc-badges"><span class="cc-badge">💎 Nitro</span>${levelBadge(lvl.level)}<span class="cc-badge">💬 ${u.messageCount || 0} messages</span></div>
                    ${actions || ''}
                    <div class="cc-card-section"><h6>Roles</h6>${rolePills(u)}</div>
                    ${u.bio ? `<div class="cc-card-section"><h6>About me</h6>${esc(u.bio)}</div>` : ''}
                    <div class="cc-card-section"><h6>Level ${lvl.level}${lvl.level >= MAX_LEVEL ? ' · MAX' : ` / ${MAX_LEVEL}`}</h6>
                        <div class="cc-xpbar" style="width:100%"><div style="width:${lvl.pct}%"></div></div>
                        ${lvl.level >= MAX_LEVEL
                            ? '<span class="cc-xp-need">👑 Max level reached!</span>'
                            : `<span class="cc-xp-need"><b>${XP_PER_LEVEL - lvl.into} XP</b> needed to reach <b>level ${lvl.level + 1}</b></span>
                               <span class="cc-xptext">${lvl.into} / ${XP_PER_LEVEL} XP · about ${Math.ceil((XP_PER_LEVEL - lvl.into) / 5)} more messages · ${u.xp || 0} XP total</span>`}
                    </div>
                    ${joined ? `<div class="cc-card-section"><h6>Member since</h6>${esc(joined)}</div>` : ''}
                </div>
            </div>
        </div>`;
    }

    const knownUsers = new Map();
    // Friends, incoming and outgoing friend requests (refreshed by pollSocial).
    let social = { friends: [], incoming: [], outgoing: [] };
    function relation(userId) {
        if (social.friends.some((f) => f.id === userId)) return 'friends';
        if (social.incoming.some((f) => f.id === userId)) return 'incoming';
        if (social.outgoing.some((f) => f.id === userId)) return 'outgoing';
        return 'none';
    }
    // Owner &amp; mods can kick/ban, verify and edit the level/XP of members; only the owner can moderate mods or hand out the Mod role.
    const canModerate = (u) => isStaff(me) &amp;&amp; u.id !== me.id &amp;&amp; u.role !== 'owner' &amp;&amp; (me.role === 'owner' || u.role !== 'mod');

    function popoutActions(u) {
        if (!me || u.id === me.id) return '';
        const btn = (act, label, cls) => `<button type="button" class="cc-btn ${cls || ''}" data-act="${act}">${label}</button>`;
        let friendBtns = '';
        switch (relation(u.id)) {
            case 'friends': friendBtns = btn('dm', '💬 Message', 'cc-btn-primary') + btn('unfriend', 'Remove friend', 'cc-btn-ghost'); break;
            case 'incoming': friendBtns = btn('befriend', '✅ Accept friend', 'cc-btn-primary') + btn('unfriend', 'Decline', 'cc-btn-ghost'); break;
            case 'outgoing': friendBtns = `<span class="cc-hint">Friend request sent</span>` + btn('unfriend', 'Cancel', 'cc-btn-ghost'); break;
            default: friendBtns = btn('befriend', '➕ Add Friend', 'cc-btn-primary');
        }
        let mod = '';
        if (canModerate(u)) {
            if (u.banned) mod += btn('unban', 'Unban');
            else mod += btn('kick', '👢 Kick', 'cc-btn-danger') + btn('ban', '🔨 Ban', 'cc-btn-danger');
            if (me.role === 'owner' &amp;&amp; !u.banned) mod += u.role === 'mod' ? btn('unmod', 'Remove Mod') : btn('mod', '🛡️ Make Mod', 'cc-btn-mod');
            // Staff are always Verified, so only members can be verified or unverified.
            if (u.role === 'member' &amp;&amp; !u.banned) mod += u.verified ? btn('unverify', 'Remove Verified') : btn('verify', '✔ Verify', 'cc-btn-verify');
            mod += btn('setLevel', '📊 Set level') + btn('addXp', '✨ Add XP');
        }
        return `<div class="cc-card-actions">${friendBtns}</div>${mod ? `<div class="cc-card-actions cc-card-mod"><h6>Moderation</h6>${mod}</div>` : ''}`;
    }

    let popoutUser = null;
    function openPopout(userId, anchor) {
        const u = me &amp;&amp; userId === me.id ? me : knownUsers.get(userId);
        if (!u) return;
        popoutUser = u.id;
        els.popout.innerHTML = profileCardHtml(u, popoutActions(u));
        els.popout.classList.remove('hidden');
        const r = anchor.getBoundingClientRect();
        const w = 300, h = els.popout.offsetHeight;
        let left = r.right + 10;
        if (left + w > window.innerWidth - 10) left = Math.max(10, r.left - w - 10);
        const top = Math.max(56, Math.min(r.top, window.innerHeight - h - 10));
        els.popout.style.left = left + 'px';
        els.popout.style.top = top + 'px';
    }
    const closePopout = () => { els.popout.classList.add('hidden'); popoutUser = null; };
    // Re-draw the open="true" card in place (e.g. after adding a friend) without moving it.
    function refreshPopout() {
        if (popoutUser == null || els.popout.classList.contains('hidden')) return;
        const u = me &amp;&amp; popoutUser === me.id ? me : knownUsers.get(popoutUser);
        if (u) els.popout.innerHTML = profileCardHtml(u, popoutActions(u));
    }

    const MOD_CONFIRM = {
        kick: (n) => `Kick ${n}? They'll be logged out and can't come back for 5 minutes.`,
        ban: (n) => `Ban ${n}? They won't be able to log in or chat until they're unbanned.`,
        mod: (n) => `Give ${n} the Mod role? Mods can kick and ban members.`,
        unmod: (n) => `Remove the Mod role from ${n}?`,
        unverify: (n) => `Remove the Verified role from ${n}? They won't be able to send photos or GIFs.`,
    };
    const MOD_DONE = {
        kick: '👢 Kicked', ban: '🔨 Banned', unban: '✅ Unbanned', mod: '🛡️ Mod role given to', unmod: 'Mod role removed from',
        verify: '✔ Verified', unverify: 'Verified role removed from',
    };
    // Asks for the new level / XP amount; returns the extra request fields or null if cancelled.
    function levelPrompt(u, action) {
        const ask = action === 'setLevel'
            ? `Set ${u.username}'s level (1–${MAX_LEVEL}). They're level ${u.level || levelInfo(u.xp || 0).level} now.`
            : `How much XP do you want to give ${u.username}? (${XP_PER_LEVEL} XP = 1 level)`;
        const raw = prompt(ask, action === 'setLevel' ? String(u.level || 1) : String(XP_PER_LEVEL));
        if (raw == null || !raw.trim()) return null;
        const n = Number(raw.trim());
        return action === 'setLevel' ? { level: n } : { amount: n };
    }

    async="true" function moderate(u, action) {
        if (MOD_CONFIRM[action] &amp;&amp; !confirm(MOD_CONFIRM[action](u.username))) return;
        let extra = {};
        if (action === 'setLevel' || action === 'addXp') {
            extra = levelPrompt(u, action);
            if (!extra) return;
        }
        const { ok, data } = await api('/moderate', { method: 'POST', json: { userId: u.id, action, ...extra } });
        if (!ok) { toast(data.error || 'That did not work.'); return; }
        knownUsers.set(data.user.id, Object.assign({}, knownUsers.get(data.user.id), data.user));
        onlineUsers = onlineUsers.map((x) => (x.id === data.user.id ? Object.assign({}, x, data.user) : x));
        if (action === 'setLevel') toast(`📊 ${data.user.username} is now level ${data.user.level}`);
        else if (action === 'addXp') toast(`✨ Gave ${data.user.username} ${extra.amount} XP — now level ${data.user.level}`);
        else toast(`${MOD_DONE[action]} ${data.user.username}`);
        if (action === 'kick' || action === 'ban') onlineUsers = onlineUsers.filter((x) => x.id !== u.id);
        if (sideTab === 'banned') loadBanned();
        else renderSide();
        refreshPopout();
    }

    async="true" function friendAction(userId, add) {
        const { ok, data } = await api('/friends', { method: add ? 'POST' : 'DELETE', json: { userId } });
        if (!ok) { toast(data.error || 'That did not work.'); return; }
        if (data.status === 'friends') toast('🤝 You are now friends!');
        else if (data.status === 'outgoing') toast('📨 Friend request sent');
        await pollSocial();
        refreshPopout();
    }

    els.popout.addEventListener('click', (e) => {
        const b = e.target.closest('[data-act]');
        if (!b || popoutUser == null) return;
        const u = knownUsers.get(popoutUser);
        if (!u) return;
        const act = b.dataset.act;
        if (act === 'dm') { closePopout(); openDm(u.id); }
        else if (act === 'befriend') friendAction(u.id, true);
        else if (act === 'unfriend') friendAction(u.id, false);
        else moderate(u, act);
    });

    document.addEventListener('click', (e) => {
        const dmBtn = e.target.closest('[data-dm]');
        if (dmBtn &amp;&amp; els.side.contains(dmBtn)) { e.stopPropagation(); openDm(Number(dmBtn.dataset.dm)); return; }
        const fBtn = e.target.closest('[data-friend]');
        if (fBtn &amp;&amp; els.side.contains(fBtn)) { e.stopPropagation(); friendAction(Number(fBtn.dataset.id), fBtn.dataset.friend === 'accept'); return; }
        const target = e.target.closest('[data-user]');
        if (target &amp;&amp; [els.list, els.me, els.sideBody, els.dmList, els.dmWho].some((c) => c.contains(target))) {
            e.stopPropagation();
            openPopout(Number(target.dataset.user), target);
            return;
        }
        if (!els.popout.contains(e.target)) closePopout();
        if (!els.emojiPicker.contains(e.target) &amp;&amp; e.target !== els.emojiBtn) els.emojiPicker.classList.add('hidden');
    });

    // ---------- rendering ----------
    function renderMe() {
        if (!me) return;
        const lvl = levelInfo(me.xp);
        els.me.innerHTML = `${avatarHtml(me, 'sm')}<div class="cc-me-info">${nameHtml(me)}
            <div class="cc-xpbar"><div style="width:${lvl.pct}%"></div></div>
            <span class="cc-xptext">LV ${lvl.level}${lvl.level >= MAX_LEVEL ? ' · MAX' : ` · ${lvl.into}/${XP_PER_LEVEL} XP`}</span></div>`;
    }

    function sameGroup(prev, msg) {
        // OWNER / MOD tags show on every message staff send, so their messages never collapse.
        return prev &amp;&amp; prev.author.id === msg.author.id &amp;&amp; !isStaff(msg.author) &amp;&amp;
            new Date(msg.createdAt) - new Date(prev.createdAt) < GROUP_WINDOW_MS &amp;&amp;
            new Date(msg.createdAt).toDateString() === new Date(prev.createdAt).toDateString();
    }

    function dayDivider(msg) {
        const div = document.createElement('div');
        div.className = 'cc-day';
        div.textContent = new Date(msg.createdAt).toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });
        return div;
    }

    function messageEl(msg, prev) {
        knownUsers.set(msg.author.id, msg.author);
        const own = me &amp;&amp; msg.author.id === me.id;
        const cont = sameGroup(prev, msg);
        const el = document.createElement('div');
        el.className = 'cc-msg' + (own ? ' cc-own' : '') + (cont ? ' cc-cont' : '');
        el.dataset.id = msg.id;
        const mention = !own &amp;&amp; me &amp;&amp; new RegExp('(^|\\s)@' + me.username.replace(/[.*+?^${}()|[\]\\]/g, '\\$&amp;') + '\\b', 'i').test(msg.content);
        const text = msg.content
            ? `<div class="cc-bubble${emojiOnly(msg.content) ? ' cc-jumbo' : ''}${mention ? ' cc-mention' : ''}">${formatContent(msg.content)}</div>` : '';
        const img = (msg.image ? `<img class="cc-msg-img" src="${esc(msg.image)}" alt="Shared photo" loading="lazy"/>` : '') +
            (msg.gif ? `<img class="cc-msg-img cc-msg-gif" src="${esc(msg.gif)}" alt="GIF" loading="lazy" referrerpolicy="no-referrer"/>` : '');
        const head = cont ? '' : `<div class="cc-msg-head">${nameHtml(msg.author, true)}${roleBadges(msg.author)}${levelBadge(msg.author.level)}<span class="cc-time">${esc(formatTime(msg.createdAt))}</span></div>`;
        el.innerHTML = `<div class="cc-msg-gutter">${cont ? '' : avatarHtml(msg.author)}</div>
            <div class="cc-msg-body" title="${esc(formatTime(msg.createdAt))}">${head}${text}${img}</div>`;
        el.querySelectorAll('.cc-msg-img').forEach((imgEl) => imgEl.addEventListener('load', () => { if (nearBottom(400)) scrollToBottom(); }));
        return el;
    }

    const nearBottom = (px = 120) => els.messages.scrollHeight - els.messages.scrollTop - els.messages.clientHeight < px;
    const scrollToBottom = () => { els.messages.scrollTop = els.messages.scrollHeight; els.jump.classList.add('hidden'); };

    function appendMessages(msgs, forceScroll) {
        const fresh = msgs.filter((m) => !seen.has(m.id));
        if (!fresh.length) return 0;
        const stick = forceScroll || nearBottom();
        let othersCount = 0;
        fresh.forEach((m) => {
            seen.add(m.id);
            if (!lastRendered || new Date(m.createdAt).toDateString() !== new Date(lastRendered.createdAt).toDateString()) {
                els.list.appendChild(dayDivider(m));
            }
            els.list.appendChild(messageEl(m, lastRendered));
            lastRendered = m;
            if (!firstRendered) firstRendered = m;
            lastId = Math.max(lastId, m.id);
            if (!oldestId || m.id < oldestId) oldestId = m.id;
            if (!me || m.author.id !== me.id) othersCount++;
        });
        if (stick) scrollToBottom();
        else if (othersCount) els.jump.classList.remove('hidden');
        return othersCount;
    }

    function prependMessages(msgs) {
        const fresh = msgs.filter((m) => !seen.has(m.id));
        if (!fresh.length) return;
        const before = els.messages.scrollHeight;
        const frag = document.createDocumentFragment();
        let prev = null;
        fresh.forEach((m) => {
            seen.add(m.id);
            if (!prev || new Date(m.createdAt).toDateString() !== new Date(prev.createdAt).toDateString()) frag.appendChild(dayDivider(m));
            frag.appendChild(messageEl(m, prev));
            prev = m;
            if (!oldestId || m.id < oldestId) oldestId = m.id;
        });
        // The day divider at the top of the existing list is redundant if the day matches.
        const firstChild = els.list.firstElementChild;
        if (firstRendered &amp;&amp; prev &amp;&amp; firstChild &amp;&amp; firstChild.classList.contains('cc-day') &amp;&amp;
            new Date(prev.createdAt).toDateString() === new Date(firstRendered.createdAt).toDateString()) firstChild.remove();
        els.list.insertBefore(frag, els.list.firstChild);
        firstRendered = fresh[0];
        els.messages.scrollTop += els.messages.scrollHeight - before;
    }

    function renderHistoryStatus() {
        els.historyStatus.innerHTML = hasMore
            ? (loadingOlder ? 'Loading older messages…' : '')
            : '<h3>Welcome to #general!</h3>This is the start of the chat. Say hi 👋';
    }

    function renderTyping(names) {
        if (!names.length) { els.typing.innerHTML = ''; return; }
        let text;
        if (names.length === 1) text = `<b>${esc(names[0])}</b> is typing…`;
        else if (names.length === 2) text = `<b>${esc(names[0])}</b> and <b>${esc(names[1])}</b> are typing…`;
        else if (names.length === 3) text = `<b>${esc(names[0])}</b>, <b>${esc(names[1])}</b> and <b>${esc(names[2])}</b> are typing…`;
        else text = 'Several people are typing…';
        els.typing.innerHTML = `<span class="cc-dots"><span></span><span></span><span></span></span><span>${text}</span>`;
    }

    function setMe(next) {
        const prevLevel = me ? levelInfo(me.xp).level : null;
        const prevRole = me ? me.role : null;
        me = next;
        if (prevRole &amp;&amp; prevRole !== me.role) {
            toast(me.role === 'mod' ? '🛡️ The owner made you a Mod! You can now kick and ban.' : me.role === 'member' ? 'Your Mod role was removed.' : '👑 Owner');
            renderSide();
        }
        knownUsers.set(me.id, me);
        renderMe();
        const lvl = levelInfo(me.xp).level;
        if (prevLevel &amp;&amp; lvl > prevLevel) toast(lvl >= MAX_LEVEL ? `👑 MAX LEVEL! You reached level ${MAX_LEVEL}!` : `🎉 Level up! You're now level ${lvl}`);
    }

    // ---------- online list, friends &amp; banned ----------
    let onlineUsers = [];
    let bannedUsers = [];
    let sideTab = 'online';
    let sideOpen = window.matchMedia('(min-width: 1000px)').matches;
    let lastSocialAt = 0;
    let lastSocialPrimed = false; // skip "new message" toasts on the first load
    const dmUnreadTotal = () => social.friends.reduce((n, f) => n + (f.unread || 0), 0);

    function personRow(u, extra) {
        knownUsers.set(u.id, Object.assign({}, knownUsers.get(u.id), u));
        const status = u.statusEmoji || u.statusText ? `<span class="cc-person-status">${esc(u.statusEmoji)} ${esc(u.statusText)}</span>` : '';
        const dot = u.online === undefined ? '' : `<i class="cc-dot${u.online ? ' on' : ''}" title="${u.online ? 'Online' : 'Offline'}"></i>`;
        return `<div class="cc-person" data-user="${u.id}">
            <div class="cc-person-avatar">${avatarHtml(u, 'sm')}${dot}</div>
            <div class="cc-person-info"><div class="cc-person-name">${nameHtml(u)}${roleBadges(u)}</div>${status}</div>
            ${extra || ''}
        </div>`;
    }

    function renderSide() {
        if (!me) return;
        els.onlineCount.textContent = onlineUsers.length;
        const requests = social.incoming.length;
        const pending = dmUnreadTotal() + requests;
        els.friendsBadge.textContent = pending > 99 ? '99+' : String(pending);
        els.friendsBadge.classList.toggle('hidden', !pending);
        els.peopleBadge.textContent = els.friendsBadge.textContent;
        els.peopleBadge.classList.toggle('hidden', !pending);
        els.bannedTab.classList.toggle('hidden', !isStaff(me));
        if (sideTab === 'banned' &amp;&amp; !isStaff(me)) sideTab = 'online';
        document.querySelectorAll('.cc-side-tab').forEach((t) => t.classList.toggle('active', t.dataset.tab === sideTab));
        updateBadge();

        let html = '';
        if (sideTab === 'online') {
            const groups = [['owner', '👑 Owner'], ['mod', '🛡️ Mods'], ['verified', '✔ Verified'], ['member', '👥 Members']];
            const groupOf = (u) => (u.role === 'owner' || u.role === 'mod' ? u.role : u.verified ? 'verified' : 'member');
            for (const [role, label] of groups) {
                const list = onlineUsers.filter((u) => groupOf(u) === role);
                if (list.length) html += `<h5>${label} — ${list.length}</h5>` + list.map((u) => personRow(u)).join('');
            }
            if (!html) html = '<p class="cc-side-empty">Nobody else is here right now.</p>';
        } else if (sideTab === 'friends') {
            if (social.incoming.length) {
                html += `<h5>Friend requests — ${social.incoming.length}</h5>` + social.incoming.map((u) => personRow(u,
                    `<button class="cc-mini-btn cc-mini-ok" data-friend="accept" data-id="${u.id}" title="Accept">✓</button><button class="cc-mini-btn" data-friend="decline" data-id="${u.id}" title="Decline">✕</button>`)).join('');
            }
            html += `<h5>Friends — ${social.friends.length}</h5>`;
            html += social.friends.length
                ? social.friends.map((u) => personRow(u,
                    `${u.unread ? `<span class="cc-count-badge">${u.unread > 99 ? '99+' : u.unread}</span>` : ''}<button class="cc-mini-btn" data-dm="${u.id}" title="Message">💬</button>`)).join('')
                : '<p class="cc-side-empty">No friends yet — click someone\'s name and hit “Add Friend”.</p>';
            if (social.outgoing.length) {
                html += `<h5>Pending — ${social.outgoing.length}</h5>` + social.outgoing.map((u) => personRow(u,
                    `<button class="cc-mini-btn" data-friend="cancel" data-id="${u.id}" title="Cancel request">✕</button>`)).join('');
            }
        } else {
            html = bannedUsers.length
                ? `<h5>Banned — ${bannedUsers.length}</h5>` + bannedUsers.map((u) => personRow(u)).join('') + '<p class="cc-side-empty">Click someone to unban them.</p>'
                : '<p class="cc-side-empty">Nobody is banned.</p>';
        }
        // Skip identical re-renders so a click on a row isn't swallowed by the 2s poll.
        if (html !== lastSideHtml) els.sideBody.innerHTML = lastSideHtml = html;
    }
    let lastSideHtml = '';

    async="true" function loadBanned() {
        const { ok, data } = await api('/moderate');
        if (ok) bannedUsers = data.banned || [];
        renderSide();
    }

    async="true" function pollSocial() {
        if (!token || !me) return;
        lastSocialAt = Date.now();
        const before = new Map(social.friends.map((f) => [f.id, f.unread || 0]));
        const prevIncoming = new Set(social.incoming.map((u) => u.id));
        const { ok, data } = await api('/friends');
        if (!ok) return;
        social = { friends: data.friends || [], incoming: data.incoming || [], outgoing: data.outgoing || [] };
        // Let people know about new private messages and friend requests.
        social.friends.forEach((f) => {
            if (lastSocialPrimed &amp;&amp; f.unread > (before.get(f.id) || 0) &amp;&amp; dm.userId !== f.id) toast(`💬 New message from ${f.username}`);
        });
        if (lastSocialPrimed) social.incoming.forEach((u) => { if (!prevIncoming.has(u.id)) toast(`📨 ${u.username} sent you a friend request`); });
        lastSocialPrimed = true;
        renderSide();
    }

    function setSideOpen(open) {
        sideOpen = open;
        els.side.classList.toggle('hidden', !open || !me || els.chat.classList.contains('hidden'));
        els.peopleBtn.classList.toggle('active', open);
        if (open) renderSide();
    }
    els.peopleBtn.addEventListener('click', () => setSideOpen(!sideOpen));
    els.sideClose.addEventListener('click', () => setSideOpen(false));
    document.querySelectorAll('.cc-side-tab').forEach((t) => t.addEventListener('click', () => {
        sideTab = t.dataset.tab;
        if (sideTab === 'banned') loadBanned();
        else renderSide();
    }));

    // ---------- private messages ----------
    const dm = { userId: null, user: null, lastId: 0, oldestId: 0, hasMore: false, last: null, first: null, seen: new Set(), loading: false, sending: false };

    function dmAsMessage(m) {
        return { id: m.id, content: m.content, image: null, createdAt: m.createdAt, author: m.senderId === me.id ? me : dm.user };
    }

    function renderDmHeader() {
        const u = dm.user;
        if (!u) { els.dmWho.innerHTML = ''; return; }
        els.dmWho.innerHTML = `<span class="cc-at-sign">@</span><span class="cc-clickable-wrap" data-user="${u.id}">${nameHtml(u)}</span>${roleBadges(u)}
            <span class="cc-online${u.online ? '' : ' cc-offline'}"><i></i>${u.online ? 'Online' : 'Offline'}</span>`;
        els.dmInput.placeholder = `Message @${u.username}`;
    }

    function renderDmStatus(friends) {
        if (friends === false) { els.dmStatus.innerHTML = '<h3>You\'re not friends anymore</h3>Add each other as friends again to keep chatting.'; return; }
        els.dmStatus.innerHTML = dm.hasMore ? (dm.loading ? 'Loading older messages…' : '')
            : `<h3>@${esc(dm.user ? dm.user.username : '')}</h3>This is the start of your private conversation. Only you two can see it.`;
    }

    function appendDm(rows, force) {
        const stick = force || els.dmMessages.scrollHeight - els.dmMessages.scrollTop - els.dmMessages.clientHeight < 120;
        rows.filter((m) => !dm.seen.has(m.id)).forEach((raw) => {
            const m = dmAsMessage(raw);
            dm.seen.add(m.id);
            if (!dm.last || new Date(m.createdAt).toDateString() !== new Date(dm.last.createdAt).toDateString()) els.dmList.appendChild(dayDivider(m));
            els.dmList.appendChild(messageEl(m, dm.last));
            dm.last = m;
            if (!dm.first) dm.first = m;
            dm.lastId = Math.max(dm.lastId, m.id);
            if (!dm.oldestId || m.id < dm.oldestId) dm.oldestId = m.id;
        });
        if (stick) els.dmMessages.scrollTop = els.dmMessages.scrollHeight;
    }

    function prependDm(rows) {
        const fresh = rows.filter((m) => !dm.seen.has(m.id)).map(dmAsMessage);
        if (!fresh.length) return;
        const before = els.dmMessages.scrollHeight;
        const frag = document.createDocumentFragment();
        let prev = null;
        fresh.forEach((m) => {
            dm.seen.add(m.id);
            if (!prev || new Date(m.createdAt).toDateString() !== new Date(prev.createdAt).toDateString()) frag.appendChild(dayDivider(m));
            frag.appendChild(messageEl(m, prev));
            prev = m;
            if (!dm.oldestId || m.id < dm.oldestId) dm.oldestId = m.id;
        });
        const firstChild = els.dmList.firstElementChild;
        if (dm.first &amp;&amp; prev &amp;&amp; firstChild &amp;&amp; firstChild.classList.contains('cc-day') &amp;&amp;
            new Date(prev.createdAt).toDateString() === new Date(dm.first.createdAt).toDateString()) firstChild.remove();
        els.dmList.insertBefore(frag, els.dmList.firstChild);
        dm.first = fresh[0];
        els.dmMessages.scrollTop += els.dmMessages.scrollHeight - before;
    }

    function applyDmData(data) {
        dm.user = Object.assign({}, knownUsers.get(data.user.id), data.user);
        knownUsers.set(dm.user.id, dm.user);
        renderDmHeader();
        const canSend = data.friends;
        els.dmInput.disabled = !canSend;
        els.dmSend.disabled = !canSend;
        renderDmStatus(canSend ? undefined : false);
    }

    async="true" function openDm(userId) {
        if (!me) return;
        closePopout();
        if (!window.matchMedia('(min-width: 1000px)').matches) setSideOpen(false);
        Object.assign(dm, { userId, user: knownUsers.get(userId) || null, lastId: 0, oldestId: 0, hasMore: false, last: null, first: null, loading: false });
        dm.seen.clear();
        els.dmList.innerHTML = '';
        showError(els.dmError, '');
        els.dmInput.value = '';
        els.dm.classList.remove('hidden');
        renderDmHeader();
        const { ok, data } = await api('/dms?with=' + userId);
        if (!ok || dm.userId !== userId) { if (!ok) showError(els.dmError, data.error || 'Could not open="true" this conversation.'); return; }
        dm.hasMore = data.hasMore;
        applyDmData(data);
        appendDm(data.messages, true);
        if (data.friends) renderDmStatus();
        if (window.matchMedia('(min-width: 641px)').matches) els.dmInput.focus();
        pollSocial();
    }

    function closeDm() {
        dm.userId = null;
        dm.user = null;
        els.dm.classList.add('hidden');
    }
    els.dmBack.addEventListener('click', closeDm);

    let dmPolling = false;
    async="true" function pollDm() {
        if (dmPolling || dm.userId == null) return;
        dmPolling = true;
        const userId = dm.userId;
        try {
            const { ok, data } = await api('/dms?with=' + userId + (dm.lastId ? '&amp;after=' + dm.lastId : ''));
            if (!ok || dm.userId !== userId) return;
            applyDmData(data);
            appendDm(data.messages);
            if (data.friends) renderDmStatus();
        } catch (e) {
        } finally {
            dmPolling = false;
        }
    }

    els.dmMessages.addEventListener('scroll', async="true" () => {
        if (els.dmMessages.scrollTop > 120 || !dm.hasMore || dm.loading || !dm.oldestId) return;
        const userId = dm.userId;
        dm.loading = true;
        renderDmStatus();
        try {
            const { ok, data } = await api('/dms?with=' + userId + '&amp;before=' + dm.oldestId);
            if (ok &amp;&amp; dm.userId === userId) { dm.hasMore = data.hasMore; prependDm(data.messages); }
        } finally {
            dm.loading = false;
            renderDmStatus();
        }
    });

    function dmAutosize() {
        els.dmInput.style.height = 'auto';
        els.dmInput.style.height = Math.min(160, els.dmInput.scrollHeight) + 'px';
    }
    async="true" function sendDm() {
        const content = els.dmInput.value.trim();
        if (!content || dm.sending || dm.userId == null) return;
        dm.sending = true;
        els.dmSend.disabled = true;
        try {
            const { ok, data } = await api('/dms', { method: 'POST', json: { to: dm.userId, content } });
            if (!ok) { showError(els.dmError, data.error || 'Message failed to send.'); return; }
            els.dmInput.value = '';
            dmAutosize();
            appendDm([data.message], true);
        } catch (e) {
            showError(els.dmError, 'Message failed to send — check your connection.');
        } finally {
            dm.sending = false;
            els.dmSend.disabled = false;
            els.dmInput.focus();
        }
    }
    els.dmInput.addEventListener('input', () => { dmAutosize(); showError(els.dmError, ''); });
    els.dmInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' &amp;&amp; !e.shiftKey &amp;&amp; !e.isComposing) { e.preventDefault(); sendDm(); }
    });
    els.dmSend.addEventListener('click', sendDm);

    // ---------- views ----------
    function showLogin() {
        els.chat.classList.add('hidden');
        els.side.classList.add('hidden');
        closeDm();
        els.login.classList.remove('hidden');
        stopPolling();
    }

    function resetRoom() {
        els.list.innerHTML = '';
        seen.clear();
        knownUsers.clear();
        social = { friends: [], incoming: [], outgoing: [] };
        onlineUsers = []; bannedUsers = []; sideTab = 'online'; lastSocialAt = 0; lastSocialPrimed = false; lastSideHtml = '';
        closeDm();
        lastId = 0; oldestId = 0; hasMore = true; lastRendered = null; firstRendered = null; unread = 0;
        updateBadge();
    }

    async="true" function enterChat() {
        els.login.classList.add('hidden');
        els.chat.classList.remove('hidden');
        setSideOpen(sideOpen);
        renderMe();
        if (!lastId) {
            const { ok, data } = await api('/messages');
            if (!ok) return;
            hasMore = data.hasMore;
            appendMessages(data.messages, true);
            applyPoll(data);
            renderHistoryStatus();
        }
        startPolling();
        if (!lastSocialAt) pollSocial();
        scrollToBottom();
        if (window.matchMedia('(min-width: 641px)').matches) els.input.focus();
    }

    function logout(expired) {
        if (!expired &amp;&amp; token) api('/logout', { method: 'POST' }).catch(() => {});
        token = null;
        me = null;
        try { localStorage.removeItem(TOKEN_KEY); } catch (e) {}
        resetRoom();
        els.settings.classList.add('hidden');
        showLogin();
        if (expired) showError(els.loginError, 'Your session ended — please log in again.');
    }

    // ---------- log in / sign up ----------
    let authMode = 'login';
    function setAuthMode(mode) {
        authMode = mode;
        const signup = mode === 'signup';
        const owner = mode === 'owner';
        els.loginForm.classList.toggle('cc-owner-mode', owner);
        els.ownerBtn.classList.toggle('on', owner);
        els.ownerBtn.setAttribute('aria-pressed', String(owner));
        document.querySelectorAll('.cc-auth-tab').forEach((t) => t.classList.toggle('active', t.dataset.auth === mode));
        document.querySelectorAll('.cc-signup-only').forEach((el) => el.classList.toggle('hidden', !signup));
        els.authTitle.textContent = owner ? '👑 Owner Login' : signup ? 'Create an account' : 'Welcome back!';
        els.authSub.textContent = owner ? 'Owner access only.' : signup ? 'Pick a username and password to join the chat.' : 'Log in to start chatting with everyone online.';
        els.loginBtn.textContent = owner ? 'Owner Log In' : signup ? 'Sign Up' : 'Log In';
        els.loginToggle.textContent = signup ? 'Already have an account? Log in' : 'Need an account? Sign up';
        els.passwordInput.placeholder = signup ? 'Choose a password' : 'Your password';
        els.passwordInput.autocomplete = signup ? 'new-password' : 'current-password';
        showError(els.loginError, '');
    }
    document.querySelectorAll('.cc-auth-tab').forEach((t) => t.addEventListener('click', () => setAuthMode(t.dataset.auth)));
    els.loginToggle.addEventListener('click', () => setAuthMode(authMode === 'login' ? 'signup' : 'login'));
    // Secret crown in the corner of the login card opens the owner login (click again to go back).
    els.ownerBtn.addEventListener('click', () => {
        setAuthMode(authMode === 'owner' ? 'login' : 'owner');
        els.loginInput.focus();
    });

    // Eye buttons that show/hide a password field.
    document.querySelectorAll('.cc-pass-toggle').forEach((btn) => btn.addEventListener('click', () => {
        const input = $(btn.dataset.target);
        const show = input.type === 'password';
        input.type = show ? 'text' : 'password';
        btn.classList.toggle('on', show);
        btn.setAttribute('aria-label', show ? 'Hide password' : 'Show password');
    }));

    els.loginForm.addEventListener('submit', async="true" (e) => {
        e.preventDefault();
        showError(els.loginError, '');
        const username = els.loginInput.value.trim();
        const password = els.passwordInput.value;
        if (!username || !password) { showError(els.loginError, 'Please enter your username and password.'); return; }
        if (authMode === 'signup') {
            if (password.length < 6) { showError(els.loginError, 'Passwords must be at least 6 characters.'); return; }
            if (password !== els.passwordConfirm.value) { showError(els.loginError, "Passwords don't match."); return; }
        }
        els.loginBtn.disabled = true;
        try {
            const { ok, data } = await api(authMode === 'signup' ? '/register' : '/login', { method: 'POST', json: { username, password } });
            if (!ok) { showError(els.loginError, data.error || 'Something went wrong, try again.'); return; }
            token = data.token;
            try { localStorage.setItem(TOKEN_KEY, token); } catch (err) {}
            resetRoom();
            setMe(data.user);
            els.loginInput.value = '';
            els.passwordInput.value = '';
            els.passwordConfirm.value = '';
            const wasOwnerLogin = authMode === 'owner';
            if (wasOwnerLogin) setAuthMode('login');
            await enterChat();
            if (wasOwnerLogin &amp;&amp; data.user.role === 'owner') toast(`👑 Welcome back, ${data.user.username}!`);
            if (authMode === 'signup') toast(`👋 Welcome to the chat, ${data.user.username}!`);
        } catch (err) {
            showError(els.loginError, 'Could not reach the chat server. Try again.');
        } finally {
            els.loginBtn.disabled = false;
        }
    });

    // ---------- polling ----------
    function applyPoll(data) {
        if (data.me) setMe(data.me);
        renderTyping(data.typing || []);
        els.online.innerHTML = `<i></i>${data.online || 0} online`;
        if (data.onlineUsers) {
            onlineUsers = data.onlineUsers;
            if (sideTab === 'online' &amp;&amp; !els.side.classList.contains('hidden')) renderSide();
            else els.onlineCount.textContent = onlineUsers.length;
        }
    }

    async="true" function poll() {
        if (polling || !token || !me) return;
        polling = true;
        try {
            const hadHistory = lastId > 0;
            const { ok, data } = await api('/messages' + (hadHistory ? '?after=' + lastId : ''));
            if (!ok) return;
            if (!hadHistory) { hasMore = data.hasMore; renderHistoryStatus(); }
            const others = appendMessages(data.messages);
            applyPoll(data);
            // Only messages that arrive after the first load count as unread.
            if (hadHistory &amp;&amp; !isChatPage() &amp;&amp; others) { unread += others; updateBadge(); }
        } catch (e) {
        } finally {
            polling = false;
        }
    }

    function startPolling() {
        stopPolling();
        const tick = () => {
            if (!document.hidden) {
                poll();
                if (dm.userId != null &amp;&amp; isChatPage()) pollDm();
                // Friends &amp; DM notifications: every 5s in the chat, every 15s elsewhere (same as the main poll).
                if (Date.now() - lastSocialAt > (isChatPage() ? 5000 : 14000)) pollSocial();
            }
            pollTimer = setTimeout(tick, isChatPage() ? 2000 : 15000);
        };
        pollTimer = setTimeout(tick, 2000);
    }
    function stopPolling() { clearTimeout(pollTimer); pollTimer = null; }
    document.addEventListener('visibilitychange', () => { if (!document.hidden &amp;&amp; isChatPage()) poll(); });

    // Scroll up for history
    els.messages.addEventListener('scroll', async="true" () => {
        if (nearBottom()) els.jump.classList.add('hidden');
        if (els.messages.scrollTop > 120 || !hasMore || loadingOlder || !oldestId) return;
        loadingOlder = true;
        renderHistoryStatus();
        try {
            const { ok, data } = await api('/messages?before=' + oldestId);
            if (ok) { hasMore = data.hasMore; prependMessages(data.messages); }
        } finally {
            loadingOlder = false;
            renderHistoryStatus();
        }
    });
    els.jump.addEventListener('click', scrollToBottom);

    // ---------- composer ----------
    function autosize() {
        els.input.style.height = 'auto';
        els.input.style.height = Math.min(160, els.input.scrollHeight) + 'px';
    }

    function sendTyping(typing) {
        if (!token) return;
        api('/typing', { method: 'POST', json: { typing } }).catch(() => {});
    }

    els.input.addEventListener('input', () => {
        autosize();
        showError(els.composerError, '');
        const now = Date.now();
        if (els.input.value.trim() &amp;&amp; now - lastTypingSent > 3000) { lastTypingSent = now; sendTyping(true); }
        if (!els.input.value.trim() &amp;&amp; lastTypingSent) { lastTypingSent = 0; sendTyping(false); }
    });
    els.input.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' &amp;&amp; !e.shiftKey &amp;&amp; !e.isComposing) { e.preventDefault(); send(); }
    });
    els.sendBtn.addEventListener('click', send);

    async="true" function send() {
        const content = els.input.value.trim();
        if ((!content &amp;&amp; !pendingImage &amp;&amp; !pendingGif) || sending) return;
        sending = true;
        els.sendBtn.disabled = true;
        const form = new FormData();
        form.append('content', content);
        if (pendingImage) form.append('image', pendingImage);
        if (pendingGif) form.append('gif', pendingGif);
        try {
            const { ok, data, status } = await api('/messages', { method: 'POST', body: form });
            if (!ok) {
                showError(els.composerError, status === 403 &amp;&amp; data.code === 'no_image_perms' ? NO_IMAGE_PERMS : (data.error || 'Message failed to send.'));
                return;
            }
            els.input.value = '';
            autosize();
            clearPendingImage();
            lastTypingSent = 0;
            appendMessages([data.message], true);
            setMe(data.me);
        } catch (e) {
            showError(els.composerError, 'Message failed to send — check your connection.');
        } finally {
            sending = false;
            els.sendBtn.disabled = false;
            els.input.focus();
        }
    }

    // Photos &amp; GIFs: only for users with the Verified role
    function requireImagePerms() {
        if (me &amp;&amp; me.imagePerms) return true;
        showError(els.composerError, NO_IMAGE_PERMS);
        return false;
    }
    function setPendingImage(file) {
        if (!file || !requireImagePerms()) return;
        if (!/^image\/(png|jpeg|gif|webp)$/.test(file.type)) { showError(els.composerError, 'Images must be PNG, JPG, GIF or WebP.'); return; }
        if (file.size > 4 * 1024 * 1024) { showError(els.composerError, 'Images must be under 4 MB.'); return; }
        pendingImage = file;
        pendingGif = null;
        const url = URL.createObjectURL(file);
        els.imagePreview.innerHTML = `<img src="${url}" alt=""/><span>${esc(file.name)}</span><button class="cc-icon-btn" aria-label="Remove image">✕</button>`;
        els.imagePreview.querySelector('button').onclick = clearPendingImage;
        els.imagePreview.classList.remove('hidden');
        showError(els.composerError, '');
    }
    function clearPendingImage() {
        pendingImage = null;
        pendingGif = null;
        els.imagePreview.innerHTML = '';
        els.imagePreview.classList.add('hidden');
        els.fileInput.value = '';
    }
    els.uploadBtn.addEventListener('click', () => { if (requireImagePerms()) els.fileInput.click(); });

    // Linked GIFs (Giphy / Tenor / any https .gif link). GIF files can also be uploaded like photos.
    const isGifLink = (v) => /^https:\/\/((media\d*|i)\.giphy\.com|media\d*\.tenor\.com|c\.tenor\.com)\//i.test(v) || /^https:\/\/[^\s?#]+\.gif([?#]\S*)?$/i.test(v);
    function setPendingGif(url) {
        if (!requireImagePerms()) return;
        if (!isGifLink(url)) { showError(els.composerError, 'Paste a direct GIF link (Giphy, Tenor or a link ending in .gif). Right-click a GIF → “Copy image address”.'); return; }
        pendingImage = null;
        els.fileInput.value = '';
        pendingGif = url;
        els.imagePreview.innerHTML = `<img src="${esc(url)}" alt="" referrerpolicy="no-referrer"/><span>GIF</span><button class="cc-icon-btn" aria-label="Remove GIF">✕</button>`;
        els.imagePreview.querySelector('button').onclick = clearPendingImage;
        els.imagePreview.classList.remove('hidden');
        showError(els.composerError, '');
    }
    els.gifBtn.addEventListener('click', () => {
        if (!requireImagePerms()) return;
        const url = prompt('Paste a GIF link (Giphy, Tenor or any link ending in .gif):');
        if (url &amp;&amp; url.trim()) setPendingGif(url.trim());
    });
    els.fileInput.addEventListener('change', () => setPendingImage(els.fileInput.files[0]));
    els.input.addEventListener('paste', (e) => {
        const file = [...(e.clipboardData?.files || [])].find((f) => f.type.startsWith('image/'));
        if (file) { e.preventDefault(); setPendingImage(file); return; }
        // Pasting just a GIF link attaches it as a GIF instead of plain text.
        const text = (e.clipboardData?.getData('text') || '').trim();
        if (!els.input.value.trim() &amp;&amp; isGifLink(text) &amp;&amp; me &amp;&amp; me.imagePerms) { e.preventDefault(); setPendingGif(text); }
    });
    els.messages.addEventListener('dragover', (e) => e.preventDefault());
    els.messages.addEventListener('drop', (e) => {
        e.preventDefault();
        const file = [...(e.dataTransfer?.files || [])].find((f) => f.type.startsWith('image/'));
        if (file) setPendingImage(file);
    });
    els.list.addEventListener('click', (e) => {
        if (e.target.classList.contains('cc-msg-img')) {
            els.lightbox.querySelector('img').src = e.target.src;
            els.lightbox.classList.remove('hidden');
        }
    });
    els.lightbox.addEventListener('click', () => els.lightbox.classList.add('hidden'));

    // ---------- emoji picker ----------
    const EMOJI = {
        '🕘': ['Recent', []],
        '😀': ['Smileys', '😀 😃 😄 😁 😆 😅 🤣 😂 🙂 🙃 😉 😊 😇 🥰 😍 🤩 😘 😗 😚 😋 😛 😜 🤪 😝 🤑 🤗 🤭 🤫 🤔 🤐 🤨 😐 😑 😶 😏 😒 🙄 😬 😮‍💨 🤥 😌 😔 😪 🤤 😴 😷 🤒 🤕 🤢 🤮 🥵 🥶 🥴 😵 🤯 🤠 🥳 🥸 😎 🤓 🧐 😕 😟 🙁 😮 😯 😲 😳 🥺 😦 😧 😨 😰 😥 😢 😭 😱 😖 😣 😞 😓 😩 😫 🥱 😤 😡 😠 🤬 😈 👿 💀 ☠️ 💩 🤡 👹 👺 👻 👽 👾 🤖 😺 😸 😹 😻 😼 😽 🙀 😿 😾'],
        '👋': ['People', '👋 🤚 🖐️ ✋ 🖖 👌 🤌 🤏 ✌️ 🤞 🤟 🤘 🤙 👈 👉 👆 👇 ☝️ 👍 👎 ✊ 👊 🤛 🤜 👏 🙌 👐 🤲 🤝 🙏 ✍️ 💅 🤳 💪 🦾 🧠 👀 👁️ 👅 👄 🫶 🙋 🙇 🤦 🤷 🧑‍💻 🥷 🧙 🧛 🧟 🧜 🧚'],
        '❤️': ['Hearts', '❤️ 🧡 💛 💚 💙 💜 🖤 🤍 🤎 💔 ❣️ 💕 💞 💓 💗 💖 💘 💝 💟 ♥️ 💯 💢 💥 💫 💦 💨 🕳️ 💬 💭 💤 ✨ ⭐ 🌟 🔥 ⚡ 🌈 ☯️'],
        '🐶': ['Nature', '🐶 🐱 🐭 🐹 🐰 🦊 🐻 🐼 🐨 🐯 🦁 🐮 🐷 🐸 🐵 🙈 🙉 🙊 🐔 🐧 🐦 🐤 🦆 🦅 🦉 🦇 🐺 🐗 🐴 🦄 🐝 🐛 🦋 🐌 🐞 🐢 🐍 🦖 🐙 🦑 🦀 🐬 🐳 🦈 🐊 🌵 🌲 🌴 🍀 🌸 🌹 🌻 🌙 ☀️ ⛅ ❄️ ☃️ 🌊'],
        '🍕': ['Food', '🍏 🍎 🍐 🍊 🍋 🍌 🍉 🍇 🍓 🍒 🍑 🥭 🍍 🥥 🥑 🌶️ 🌽 🥕 🥐 🍞 🧀 🥚 🍳 🥓 🍔 🍟 🍕 🌭 🥪 🌮 🌯 🍜 🍝 🍣 🍱 🍙 🍩 🍪 🎂 🍰 🧁 🍫 🍬 🍭 🍿 🧋 ☕ 🍵 🥤 🧃'],
        '⚽': ['Activities', '⚽ 🏀 🏈 ⚾ 🎾 🏐 🏉 🎱 🏓 🏸 🥊 🥋 ⛸️ 🛹 🎿 🏆 🥇 🥈 🥉 🏅 🎮 🕹️ 🎲 ♟️ 🎯 🎳 🎤 🎧 🎸 🎹 🥁 🎨 🎬 🎉 🎊 🎁 🎈 🎃 🎄'],
        '💡': ['Objects', '📱 💻 ⌨️ 🖥️ 🖱️ 💾 📷 📺 ⏰ 💡 🔦 📚 📖 ✏️ 📝 📌 📎 🔑 🔒 🔓 🛡️ ⚔️ 🔫 💣 🧨 💎 💰 💸 🚀 🛸 🚗 🏎️ ✈️ 🗿 🏠 🎌 ✅ ❌ ❓ ❗ ⚠️ 🔞 🆒 🆗 🆕 🆙'],
    };
    for (const k in EMOJI) if (typeof EMOJI[k][1] === 'string') EMOJI[k][1] = EMOJI[k][1].split(' ');

    function getRecent() { try { return JSON.parse(localStorage.getItem('yyChatRecentEmoji') || '[]'); } catch (e) { return []; } }
    function pushRecent(emoji) {
        const list = [emoji, ...getRecent().filter((x) => x !== emoji)].slice(0, 24);
        try { localStorage.setItem('yyChatRecentEmoji', JSON.stringify(list)); } catch (e) {}
    }

    function buildPicker(container, onPick) {
        container.innerHTML = `<input class="cc-emoji-search" placeholder="Search emoji by category…"/><div class="cc-emoji-tabs"></div><div class="cc-emoji-grid"></div>`;
        const tabs = container.querySelector('.cc-emoji-tabs');
        const grid = container.querySelector('.cc-emoji-grid');
        const search = container.querySelector('.cc-emoji-search');
        function render(filter) {
            EMOJI['🕘'][1] = getRecent();
            grid.innerHTML = '';
            for (const icon in EMOJI) {
                const [label, list] = EMOJI[icon];
                if (!list.length || (filter &amp;&amp; !label.toLowerCase().includes(filter))) continue;
                const h = document.createElement('h5');
                h.textContent = label;
                h.dataset.cat = icon;
                grid.appendChild(h);
                list.forEach((emo) => {
                    const b = document.createElement('button');
                    b.type = 'button';
                    b.textContent = emo;
                    b.onclick = (ev) => { ev.stopPropagation(); pushRecent(emo); onPick(emo); };
                    grid.appendChild(b);
                });
            }
        }
        Object.keys(EMOJI).forEach((icon) => {
            const t = document.createElement('button');
            t.type = 'button';
            t.textContent = icon;
            t.title = EMOJI[icon][0];
            t.onclick = (ev) => {
                ev.stopPropagation();
                search.value = '';
                render('');
                const h = grid.querySelector(`h5[data-cat="${icon}"]`);
                if (h) grid.scrollTop = h.offsetTop - grid.offsetTop;
            };
            tabs.appendChild(t);
        });
        search.addEventListener('input', () => render(search.value.trim().toLowerCase()));
        search.addEventListener('click', (ev) => ev.stopPropagation());
        container.render = () => render(search.value.trim().toLowerCase());
        render('');
    }

    buildPicker(els.emojiPicker, (emo) => {
        const start = els.input.selectionStart ?? els.input.value.length;
        const end = els.input.selectionEnd ?? start;
        els.input.value = els.input.value.slice(0, start) + emo + els.input.value.slice(end);
        els.input.selectionStart = els.input.selectionEnd = start + emo.length;
        els.input.focus();
        autosize();
    });
    els.emojiBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        els.emojiPicker.classList.toggle('hidden');
        if (!els.emojiPicker.classList.contains('hidden')) els.emojiPicker.render();
    });

    // ---------- settings ----------
    const s = {
        name: $('ccSetName'), nameHint: $('ccNameHint'), currentPass: $('ccSetCurrentPass'), currentPassWrap: $('ccCurrentPassWrap'), newPass: $('ccSetNewPass'), passLabel: $('ccPassLabel'), passHint: $('ccPassHint'),
        avatarThumb: $('ccAvatarThumb'), bannerThumb: $('ccBannerThumb'),
        avatarUpload: $('ccAvatarUpload'), avatarRemove: $('ccAvatarRemove'), avatarFile: $('ccAvatarFile'),
        bannerColor: $('ccSetBannerColor'), bannerUpload: $('ccBannerUpload'), bannerRemove: $('ccBannerRemove'), bannerFile: $('ccBannerFile'),
        bio: $('ccSetBio'), statusEmoji: $('ccSetStatusEmoji'), statusText: $('ccSetStatusText'), statusPicker: $('ccStatusEmojiPicker'),
        nameColor: $('ccSetNameColor'), gradientOn: $('ccSetGradientOn'), nameGradient: $('ccSetNameGradient'), font: $('ccSetFont'),
        decoGrid: $('ccDecoGrid'), effectGrid: $('ccEffectGrid'), nameFxGrid: $('ccNameFxGrid'), themePrimary: $('ccSetThemePrimary'), themeAccent: $('ccSetThemeAccent'),
        error: $('ccSettingsError'), save: $('ccSettingsSave'), logout: $('ccLogout'), close: $('ccSettingsClose'), preview: $('ccProfilePreview'),
    };
    let draftDecoration = 'none';
    let draftProfileEffect = 'none';
    let draftNameEffect = 'none';
    let draftStatusEmoji = '';

    function draft() {
        return Object.assign({}, me, {
            username: s.name.value.trim() || me.username,
            bannerColor: s.bannerColor.value,
            bio: s.bio.value,
            statusEmoji: draftStatusEmoji,
            statusText: s.statusText.value,
            nameColor: s.nameColor.value,
            nameGradient: s.gradientOn.checked ? s.nameGradient.value : null,
            nameFont: s.font.value,
            decoration: draftDecoration,
            profileEffect: draftProfileEffect,
            nameEffect: draftNameEffect,
            themePrimary: s.themePrimary.value,
            themeAccent: s.themeAccent.value,
        });
    }

    function renderPreview() {
        if (!me) return;
        s.preview.innerHTML = profileCardHtml(draft());
        s.nameGradient.disabled = !s.gradientOn.checked;
        s.statusEmoji.textContent = draftStatusEmoji || '🙂';
        s.decoGrid.querySelectorAll('.cc-deco-opt').forEach((b) => b.classList.toggle('active', b.dataset.deco === draftDecoration));
        s.effectGrid.querySelectorAll('.cc-deco-opt').forEach((b) => b.classList.toggle('active', b.dataset.effect === draftProfileEffect));
        // Name effect tiles show the current (unsaved) name colours.
        const d = draft();
        s.nameFxGrid.querySelectorAll('.cc-deco-opt').forEach((b) => {
            b.classList.toggle('active', b.dataset.fx === draftNameEffect);
            b.querySelector('.cc-fx-sample').innerHTML = nameHtml(Object.assign({}, d, { nameEffect: b.dataset.fx }));
        });
    }

    function buildEffectGrids() {
        s.effectGrid.innerHTML = '';
        Object.entries(PROFILE_EFFECTS).forEach(([key, fx]) => {
            const b = document.createElement('button');
            b.type = 'button';
            b.className = 'cc-deco-opt';
            b.dataset.effect = key;
            b.innerHTML = `<span class="cc-effect-icon">${fx.icon}</span>${esc(fx.label)}`;
            b.onclick = () => { draftProfileEffect = key; renderPreview(); };
            s.effectGrid.appendChild(b);
        });
        s.nameFxGrid.innerHTML = '';
        NAME_EFFECTS.forEach((key) => {
            const b = document.createElement('button');
            b.type = 'button';
            b.className = 'cc-deco-opt';
            b.dataset.fx = key;
            b.innerHTML = `<span class="cc-fx-sample"></span>${key}`;
            b.onclick = () => { draftNameEffect = key; renderPreview(); };
            s.nameFxGrid.appendChild(b);
        });
    }

    function buildDecoGrid() {
        s.decoGrid.innerHTML = '';
        DECORATIONS.forEach((d) => {
            const b = document.createElement('button');
            b.type = 'button';
            b.className = 'cc-deco-opt';
            b.dataset.deco = d;
            b.innerHTML = avatarHtml(Object.assign({}, me, { decoration: d }), 'sm') + d;
            b.onclick = () => { draftDecoration = d; renderPreview(); };
            s.decoGrid.appendChild(b);
        });
    }

    function renderThumbs() {
        s.avatarThumb.style.backgroundImage = me.avatar ? `url('${me.avatar}')` : '';
        s.avatarThumb.textContent = me.avatar ? '' : 'none';
        s.bannerThumb.style.backgroundImage = me.banner ? `url('${me.banner}')` : '';
        s.bannerThumb.style.backgroundColor = me.bannerColor;
        s.bannerThumb.textContent = '';
    }

    function fillSettings() {
        renderThumbs();
        s.name.value = me.username;
        s.nameHint.textContent = me.nextNameChangeAt
            ? `You already changed your name this week. Next change: ${new Date(me.nextNameChangeAt).toLocaleString()}.`
            : 'You can change your name once a week.';
        s.name.disabled = !!me.nextNameChangeAt;
        s.currentPass.value = '';
        s.newPass.value = '';
        s.currentPassWrap.classList.toggle('hidden', !me.hasPassword);
        s.passLabel.textContent = me.hasPassword ? 'Change password' : 'Set a password';
        s.passHint.textContent = me.hasPassword
            ? 'Leave blank to keep your current password. Changing it logs out your other devices.'
            : 'Your account has no password yet — set one so you can log in on other devices.';
        s.bannerColor.value = me.bannerColor;
        s.bio.value = me.bio || '';
        draftStatusEmoji = me.statusEmoji || '';
        s.statusText.value = me.statusText || '';
        s.nameColor.value = me.nameColor;
        s.gradientOn.checked = !!me.nameGradient;
        s.nameGradient.value = me.nameGradient || '#eb459e';
        s.font.value = me.nameFont;
        draftDecoration = me.decoration;
        draftProfileEffect = me.profileEffect || 'none';
        draftNameEffect = me.nameEffect || 'none';
        s.themePrimary.value = me.themePrimary;
        s.themeAccent.value = me.themeAccent;
        s.avatarRemove.disabled = !me.avatar;
        s.bannerRemove.disabled = !me.banner;
        showError(s.error, '');
        buildDecoGrid();
        buildEffectGrids();
        renderPreview();
    }

    function openSettings() {
        if (!me) return;
        fillSettings();
        els.settings.classList.remove('hidden');
    }
    $('ccSettingsBtn').addEventListener('click', openSettings);
    s.close.addEventListener('click', () => els.settings.classList.add('hidden'));
    els.settings.addEventListener('click', (e) => { if (e.target === els.settings) els.settings.classList.add('hidden'); });

    [s.name, s.bannerColor, s.bio, s.statusText, s.nameColor, s.gradientOn, s.nameGradient, s.font, s.themePrimary, s.themeAccent]
        .forEach((el) => el.addEventListener('input', renderPreview));
    s.font.addEventListener('change', renderPreview);
    s.gradientOn.addEventListener('change', renderPreview);

    buildPicker(s.statusPicker, (emo) => { draftStatusEmoji = emo; s.statusPicker.classList.add('hidden'); renderPreview(); });
    s.statusEmoji.addEventListener('click', (e) => {
        e.stopPropagation();
        if (draftStatusEmoji &amp;&amp; !s.statusPicker.classList.contains('hidden')) { draftStatusEmoji = ''; renderPreview(); }
        s.statusPicker.classList.toggle('hidden');
        s.statusPicker.render();
    });

    async="true" function uploadMedia(kind, file) {
        if (!file) return;
        if (!/^image\/(png|jpeg|gif|webp)$/.test(file.type)) { showError(s.error, 'Pick a PNG, JPG, GIF or WebP image.'); return; }
        if (file.size > 3 * 1024 * 1024) { showError(s.error, 'Images must be under 3 MB.'); return; }
        const form = new FormData();
        form.append('kind', kind);
        form.append('file', file);
        showError(s.error, '');
        const { ok, data } = await api('/profile', { method: 'POST', body: form });
        if (!ok) { showError(s.error, data.error || 'Upload failed.'); return; }
        setMe(data.user);
        fillSettingsMedia();
    }
    async="true" function removeMedia(kind) {
        const form = new FormData();
        form.append('remove', kind);
        const { ok, data } = await api('/profile', { method: 'POST', body: form });
        if (!ok) { showError(s.error, data.error || 'Could not remove it.'); return; }
        setMe(data.user);
        fillSettingsMedia();
    }
    // Refresh only the media-related bits so unsaved edits in the form are kept.
    function fillSettingsMedia() {
        renderThumbs();
        s.avatarRemove.disabled = !me.avatar;
        s.bannerRemove.disabled = !me.banner;
        buildDecoGrid();
        renderPreview();
    }
    s.avatarUpload.addEventListener('click', () => s.avatarFile.click());
    s.bannerUpload.addEventListener('click', () => s.bannerFile.click());
    s.avatarFile.addEventListener('change', () => { uploadMedia('avatar', s.avatarFile.files[0]); s.avatarFile.value = ''; });
    s.bannerFile.addEventListener('change', () => { uploadMedia('banner', s.bannerFile.files[0]); s.bannerFile.value = ''; });
    s.avatarRemove.addEventListener('click', () => removeMedia('avatar'));
    s.bannerRemove.addEventListener('click', () => removeMedia('banner'));

    s.save.addEventListener('click', async="true" () => {
        const d = draft();
        const body = {
            bannerColor: d.bannerColor, bio: d.bio, statusEmoji: d.statusEmoji, statusText: d.statusText,
            nameColor: d.nameColor, nameGradient: d.nameGradient, nameFont: d.nameFont, decoration: d.decoration,
            profileEffect: d.profileEffect, nameEffect: d.nameEffect,
            themePrimary: d.themePrimary, themeAccent: d.themeAccent,
        };
        if (s.newPass.value) {
            if (s.newPass.value.length < 6) { showError(s.error, 'Passwords must be at least 6 characters.'); return; }
            if (me.hasPassword &amp;&amp; !s.currentPass.value) { showError(s.error, 'Enter your current password to change it.'); return; }
            body.newPassword = s.newPass.value;
            body.currentPassword = s.currentPass.value;
        }
        const newName = s.name.value.trim();
        if (newName &amp;&amp; newName !== me.username) {
            if (!confirm(`Change your name to "${newName}"? You won't be able to change it again for a week.`)) return;
            body.username = newName;
        }
        s.save.disabled = true;
        showError(s.error, '');
        try {
            const { ok, data } = await api('/profile', { method: 'PATCH', json: body });
            if (!ok) { showError(s.error, data.error || 'Could not save your changes.'); return; }
            setMe(data.user);
            els.settings.classList.add('hidden');
            toast('✅ Profile saved');
        } finally {
            s.save.disabled = false;
        }
    });

    s.logout.addEventListener('click', () => {
        const warn = me &amp;&amp; !me.hasPassword ? " You haven't set a password, so you won't be able to log back in — set one first!" : '';
        if (confirm('Log out of the chat?' + warn)) logout(false);
    });

    // ---------- floating button &amp; navigation ----------
    function updateBadge() {
        const total = unread + dmUnreadTotal() + social.incoming.length;
        els.fabBadge.textContent = total > 99 ? '99+' : String(total);
        els.fabBadge.classList.toggle('hidden', !total);
    }
    els.fab.addEventListener('click', () => window.navigateTo('chat'));

    // Used by the site-wide settings panel's "Customize Profile" button.
    window.ccOpenProfileSettings = function () {
        if (me) { openSettings(); return true; }
        window.navigateTo('chat');
        toast('👋 Log in or sign up to customize your profile');
        return false;
    };

    function onNavigate(pageId) {
        const onChat = pageId === 'chat';
        els.fab.classList.toggle('hidden', onChat);
        closePopout();
        if (onChat) {
            unread = 0;
            updateBadge();
            if (me) { enterChat(); } else { showLogin(); }
        }
    }
    const originalNavigate = window.navigateTo;
    window.navigateTo = function (pageId) {
        originalNavigate(pageId);
        onNavigate(pageId);
    };

    // ---------- boot ----------
    (async function init() {
        renderHistoryStatus();
        if (!token) { showLogin(); return; }
        try {
            const { ok, data } = await api('/me');
            if (!ok) { if (!token) return; showLogin(); return; }
            setMe(data.user);
            if (isChatPage()) enterChat();
            else startPolling(); // light background polling for the unread badge
        } catch (e) {
            showLogin();
        }
    })();
})();
